INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8e3e4993-6df6-5241-a8c6-8380eef26ef0', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 35, 35, 'For it will come like a snare on all those who dwell on the surface of all the earth.'),
  ('43936d77-7a0f-5dca-abd6-98df9a350233', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 36, 36, 'Therefore be watchful all the time, praying that you may be counted worthy to escape all these things that will happen, and to stand before the Son of Man."'),
  ('19579992-23b6-5061-a295-fb2b9686db39', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 37, 37, 'Every day Jesus was teaching in the temple, and every night he would go out and spend the night on the mountain that is called Olivet.'),
  ('7bee73f7-f202-5c6a-ab8c-e2f50f11ddb6', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 38, 38, 'All the people came early in the morning to him in the temple to hear him.'),
  ('2ddce665-bb1a-5fcb-a24b-7bef4ac1d83f', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 1, 1, 'Now the feast of unleavened bread, which is called the Passover, drew near.'),
  ('11f55059-e33d-59c5-a17e-17121c3f62a4', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 2, 2, 'The chief priests and the scribes sought how they might put him to death, for they feared the people.'),
  ('6d937daf-93f9-5346-a03b-0b30372c6be2', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 3, 3, 'Satan entered into Judas, who was surnamed Iscariot, who was numbered with the twelve.'),
  ('f8254a3a-36af-5fea-ac1f-3318ddfb79ae', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 4, 4, 'He went away, and talked with the chief priests and captains about how he might deliver him to them.'),
  ('3c60c4ac-17ba-5c75-ace7-cdc66291ca8c', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 5, 5, 'They were glad, and agreed to give him money.'),
  ('67cb2085-f680-51a6-aa4d-e6ea392d0fa6', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 6, 6, 'He consented, and sought an opportunity to deliver him to them in the absence of the multitude.'),
  ('64f91d80-32b2-5bfe-ab49-7a81b034473d', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 7, 7, 'The day of unleavened bread came, on which the Passover must be sacrificed.'),
  ('a6c2eee3-79f7-54a2-a923-224cbb10363e', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 8, 8, 'He sent Peter and John, saying, "Go and prepare the Passover for us, that we may eat."'),
  ('70183543-ab71-5725-abd8-8ba2ea188cec', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 9, 9, 'They said to him, "Where do you want us to prepare?"'),
  ('7df95187-d41f-5ff6-ae47-81825d64c701', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 10, 10, 'He said to them, "Behold, when you have entered into the city, a man carrying a pitcher of water will meet you. Follow him into the house which he enters.'),
  ('e376041f-163c-54d2-ab99-1a18294d7906', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 11, 11, 'Tell the master of the house, ''The Teacher says to you, "Where is the guest room, where I may eat the Passover with my disciples?"'''),
  ('cf66fe43-151e-58c7-a79d-bc0950335fab', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 12, 12, 'He will show you a large, furnished upper room. Make preparations there."'),
  ('e33898dd-c992-56ca-a4c5-c943a781debd', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 13, 13, 'They went, found things as he had told them, and they prepared the Passover.'),
  ('f9e13497-3c88-5d99-a80a-6a3efb2a0fad', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 14, 14, 'When the hour had come, he sat down with the twelve apostles.'),
  ('32b52f01-4bb1-5748-ac9e-62a9bf2f1b6f', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 15, 15, 'He said to them, "I have earnestly desired to eat this Passover with you before I suffer,'),
  ('57472aab-d0ae-53cb-a915-f766635abbcc', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 16, 16, 'for I tell you, I will no longer by any means eat of it until it is fulfilled in the Kingdom of God."'),
  ('06c37cec-c060-5ca7-a8a6-e77ebdccc168', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 17, 17, 'He received a cup, and when he had given thanks, he said, "Take this, and share it among yourselves,'),
  ('a6ac0667-50a0-5186-a705-c6688b6b8953', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 18, 18, 'for I tell you, I will not drink at all again from the fruit of the vine, until the Kingdom of God comes."'),
  ('2b932f7f-b21f-584e-ae75-40c103732ae9', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 19, 19, 'He took bread, and when he had given thanks, he broke it, and gave to them, saying, "This is my body which is given for you. Do this in memory of me."'),
  ('0e81c118-6bfd-5677-a82d-d181e4424eab', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 20, 20, 'Likewise, he took the cup after supper, saying, "This cup is the new covenant in my blood, which is poured out for you.'),
  ('353170b7-226a-5275-a917-3ecc7bb8c034', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 21, 21, 'But behold, the hand of him who betrays me is with me on the table.'),
  ('8a9c4dae-1dd8-590c-ae06-b12ff2bf9aac', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 22, 22, 'The Son of Man indeed goes, as it has been determined, but woe to that man through whom he is betrayed!"'),
  ('1b6d148a-f190-5b90-a5b3-ce9e30cf9626', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 23, 23, 'They began to question among themselves, which of them it was who would do this thing.'),
  ('5ef0497c-d24a-50d7-aabd-d3005f0ef18c', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 24, 24, 'There arose also a contention among them, which of them was considered to be greatest.'),
  ('cbc43642-467a-54b0-a41a-6818ab3cc2cc', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 25, 25, 'He said to them, "The kings of the nations lord it over them, and those who have authority over them are called ''benefactors.'''),
  ('6b8a1253-d30b-541e-a571-3979ad6b7f17', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 26, 26, 'But not so with you. But one who is the greater among you, let him become as the younger, and one who is governing, as one who serves.'),
  ('2b01b45a-82a1-5df4-ac07-51c65073efe8', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 27, 27, 'For who is greater, one who sits at the table, or one who serves? Isn''t it he who sits at the table? But I am in the midst of you as one who serves.'),
  ('0f7657f3-015f-5a6b-ac44-c0322fff6edf', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 28, 28, 'But you are those who have continued with me in my trials.'),
  ('9828bcec-db82-58e5-a7d1-8ad44e6b776e', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 29, 29, 'I confer on you a kingdom, even as my Father conferred on me,'),
  ('4145aeb3-92e1-517e-a8fd-fa407e64192d', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 30, 30, 'that you may eat and drink at my table in my Kingdom. You will sit on thrones, judging the twelve tribes of Israel."'),
  ('c0706fd1-cd82-56a8-a392-25cffcc042e6', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 31, 31, 'The Lord said, "Simon, Simon, behold, Satan asked to have you, that he might sift you as wheat,'),
  ('f643af14-6f39-53aa-a11f-b753056ee756', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 32, 32, 'but I prayed for you, that your faith wouldn''t fail. You, when once you have turned again, establish your brothers."'),
  ('8137a69c-8151-5de9-abf6-c57729d8acce', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 33, 33, 'He said to him, "Lord, I am ready to go with you both to prison and to death!"'),
  ('b74b5ef5-3d76-57f9-a0ef-8018eb1ea82d', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 34, 34, 'He said, "I tell you, Peter, the rooster will by no means crow today until you deny that you know me three times."'),
  ('c83754d6-ac0f-58d1-ad04-9e2a0a069cfb', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 35, 35, 'He said to them, "When I sent you out without purse, and wallet, and shoes, did you lack anything?" They said, "Nothing."'),
  ('17b638be-c837-5e90-afa7-ea419a6dbd87', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 36, 36, 'Then he said to them, "But now, whoever has a purse, let him take it, and likewise a wallet. Whoever has none, let him sell his cloak, and buy a sword.'),
  ('d70a9a45-4dff-5cca-a936-4bc9bf1aaf5a', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 37, 37, 'For I tell you that this which is written must still be fulfilled in me: ''He was counted with transgressors.'' For that which concerns me has an end."'),
  ('0f5bcd3e-5915-562f-add9-b251d4591630', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 38, 38, 'They said, "Lord, behold, here are two swords." He said to them, "That is enough."'),
  ('a10db19a-c7d9-511e-af32-93b133a5a26c', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 39, 39, 'He came out, and went, as his custom was, to the Mount of Olives. His disciples also followed him.'),
  ('ab745d93-9698-5666-a2db-fbea2efc254c', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 40, 40, 'When he was at the place, he said to them, "Pray that you don''t enter into temptation."'),
  ('ed449628-b31c-553f-a85d-4b49f854ecc8', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 41, 41, 'He was withdrawn from them about a stone''s throw, and he knelt down and prayed,'),
  ('86d34d27-c229-5834-a6b5-a9af83fdfd9a', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 42, 42, 'saying, "Father, if you are willing, remove this cup from me. Nevertheless, not my will, but yours, be done."'),
  ('5f97d18f-c268-517d-a41e-4acd6ad36488', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 43, 43, 'An angel from heaven appeared to him, strengthening him.'),
  ('72f8b68b-c5ac-515e-a24d-e238baadc747', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 44, 44, 'Being in agony he prayed more earnestly. His sweat became like great drops of blood falling down on the ground.'),
  ('b6ff0d82-42b8-55cd-a2c4-d0fe91f237a6', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 45, 45, 'When he rose up from his prayer, he came to the disciples, and found them sleeping because of grief,'),
  ('b4844e12-0db6-596f-a238-695fc364711d', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 46, 46, 'and said to them, "Why do you sleep? Rise and pray that you may not enter into temptation."'),
  ('f108f4e8-84d8-5ed0-a067-b28c24ed5daa', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 47, 47, 'While he was still speaking, behold, a multitude, and he who was called Judas, one of the twelve, was leading them. He came near to Jesus to kiss him.'),
  ('54820d1c-b5ac-5370-ac5d-fb9701e5022b', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 48, 48, 'But Jesus said to him, "Judas, do you betray the Son of Man with a kiss?"'),
  ('be47f022-59c5-563e-ae1f-0e4d0c2c0012', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 49, 49, 'When those who were around him saw what was about to happen, they said to him, "Lord, shall we strike with the sword?"'),
  ('7f7b440a-af4d-5eda-af58-01ecefaba49a', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 50, 50, 'A certain one of them struck the servant of the high priest, and cut off his right ear.'),
  ('13bc99ab-4788-57a7-a3ee-b5d32a5cd2a5', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 51, 51, 'But Jesus answered, "Let me at least do this"--and he touched his ear, and healed him.'),
  ('bc4e682c-b689-5564-a610-2522ff2a73f5', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 52, 52, 'Jesus said to the chief priests, captains of the temple, and elders, who had come against him, "Have you come out as against a robber, with swords and clubs?'),
  ('7c5d5cf0-947b-5439-ab6c-4d614f2dd88b', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 53, 53, 'When I was with you in the temple daily, you didn''t stretch out your hands against me. But this is your hour, and the power of darkness."'),
  ('70f8eab4-b127-588b-a6ee-cc6e52580cc5', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 54, 54, 'They seized him, and led him away, and brought him into the high priest''s house. But Peter followed from a distance.'),
  ('7d4bbe52-9b45-5cd4-a8a5-ad0989a57f34', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 55, 55, 'When they had kindled a fire in the middle of the courtyard, and had sat down together, Peter sat among them.'),
  ('29dea233-ef81-5559-aaab-7943c292481d', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 56, 56, 'A certain servant girl saw him as he sat in the light, and looking intently at him, said, "This man also was with him."'),
  ('15b592d8-1612-5d42-a31a-c450cd7ed06e', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 57, 57, 'He denied Jesus, saying, "Woman, I don''t know him."'),
  ('8e60190b-2b5c-5172-adfe-e9007c503f10', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 58, 58, 'After a little while someone else saw him, and said, "You also are one of them!" But Peter answered, "Man, I am not!"'),
  ('83791a83-da09-50ce-ad00-fa30a100ffba', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 59, 59, 'After about one hour passed, another confidently affirmed, saying, "Truly this man also was with him, for he is a Galilean!"'),
  ('90017fb6-4b60-5ce7-ab1a-236974a77e7e', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 60, 60, 'But Peter said, "Man, I don''t know what you are talking about!" Immediately, while he was still speaking, a rooster crowed.'),
  ('b9b7be37-1c9b-598c-af6c-0a4087106c16', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 61, 61, 'The Lord turned, and looked at Peter. Then Peter remembered the Lord''s word, how he said to him, "Before the rooster crows you will deny me three times."'),
  ('eb646838-7949-57a3-ab73-1c281d6ca934', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 62, 62, 'He went out, and wept bitterly.'),
  ('e7026f59-2525-5ad1-ac4e-99384ef1925a', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 63, 63, 'The men who held Jesus mocked him and beat him.'),
  ('58953f2e-ceb3-5f2c-a1c6-d62e3042caec', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 64, 64, 'Having blindfolded him, they struck him on the face and asked him, "Prophesy! Who is the one who struck you?"'),
  ('503f215e-b0e7-526c-a318-d0a211482b6d', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 65, 65, 'They spoke many other things against him, insulting him.'),
  ('20c4bd7e-7543-5bce-a1d9-804fc28f2683', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 66, 66, 'As soon as it was day, the assembly of the elders of the people was gathered together, both chief priests and scribes, and they led him away into their council, saying,'),
  ('36925783-849e-5b9e-ae9c-8672d37a4041', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 67, 67, '"If you are the Christ, tell us." But he said to them, "If I tell you, you won''t believe,'),
  ('6dd84dfa-18ef-569c-a440-61af39759042', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 68, 68, 'and if I ask, you will in no way answer me or let me go.'),
  ('308727ad-7c87-57fd-a893-04575ce37686', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 69, 69, 'From now on, the Son of Man will be seated at the right hand of the power of God."'),
  ('94190c0b-5622-5135-ac2f-5a41edf913bb', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 70, 70, 'They all said, "Are you then the Son of God?" He said to them, "You say it, because I am."'),
  ('4c2dc0c0-1989-50d5-ad62-0d10944bda2c', '2a7456c2-1fbe-5a0a-aa06-623c5609d2de', NULL, 71, 71, 'They said, "Why do we need any more witness? For we ourselves have heard from his own mouth!"'),
  ('4137efd5-d61e-5d67-a1a8-6edb5fee5834', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 1, 1, 'The whole company of them rose up and brought him before Pilate.'),
  ('611d9436-a67d-5146-af6f-750c335e95a4', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 2, 2, 'They began to accuse him, saying, "We found this man perverting the nation, forbidding paying taxes to Caesar, and saying that he himself is Christ, a king."'),
  ('061b12f3-defe-54e6-ab29-ace3b8cdd32c', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 3, 3, 'Pilate asked him, "Are you the King of the Jews?" He answered him, "So you say."'),
  ('07b097b2-4f0e-563c-ab8a-55a3b5be77f4', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 4, 4, 'Pilate said to the chief priests and the multitudes, "I find no basis for a charge against this man."'),
  ('50e15edf-c6e4-5e3c-a011-9e07a1862942', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 5, 5, 'But they insisted, saying, "He stirs up the people, teaching throughout all Judea, beginning from Galilee even to this place."'),
  ('54c66566-9da3-5f09-ab36-7e630f983eb2', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 6, 6, 'But when Pilate heard Galilee mentioned, he asked if the man was a Galilean.'),
  ('c3e45914-cfbc-5e4a-a0a8-6ab68e79b7db', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 7, 7, 'When he found out that he was in Herod''s jurisdiction, he sent him to Herod, who was also in Jerusalem during those days.'),
  ('78056e06-304c-51e0-af5b-e797df2c36e5', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 8, 8, 'Now when Herod saw Jesus, he was exceedingly glad, for he had wanted to see him for a long time, because he had heard many things about him. He hoped to see some miracle done by him.'),
  ('ed556b59-4133-5bd6-ae2f-36d4ad67dfd8', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 9, 9, 'He questioned him with many words, but he gave no answers.'),
  ('c9b4a7f0-fa6a-5b0c-a56b-e30ada5e5c81', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 10, 10, 'The chief priests and the scribes stood, vehemently accusing him.'),
  ('a5cccd62-6a4e-5210-a276-89c95e0ec40d', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 11, 11, 'Herod with his soldiers humiliated him and mocked him. Dressing him in luxurious clothing, they sent him back to Pilate.'),
  ('ca540c11-3933-57de-a14d-333ddccbcf52', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 12, 12, 'Herod and Pilate became friends with each other that very day, for before that they were enemies with each other.'),
  ('e5698c30-c392-536d-a07b-f960e72e5aac', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 13, 13, 'Pilate called together the chief priests and the rulers and the people,'),
  ('7f726172-e224-510b-a0e9-c36f689cb29b', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 14, 14, 'and said to them, "You brought this man to me as one that perverts the people, and see, I have examined him before you, and found no basis for a charge against this man concerning those things of which you accuse him.'),
  ('32edfa6a-44b8-5b2d-a26f-bda901cf4efd', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 15, 15, 'Neither has Herod, for I sent you to him, and see, nothing worthy of death has been done by him.'),
  ('9db4c4ba-4ab9-585c-a5d2-7a3857ecb6b3', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 16, 16, 'I will therefore chastise him and release him."'),
  ('be9d293b-1112-5c04-a30a-40352c15bae9', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 17, 17, 'Now he had to release one prisoner to them at the feast.'),
  ('9b503e2c-3a3a-59a2-a0bd-f6b3b8283cf5', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 18, 18, 'But they all cried out together, saying, "Away with this man! Release to us Barabbas!"--'),
  ('313c14fe-e92f-5428-a35f-bc9555ce82fe', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 19, 19, 'one who was thrown into prison for a certain revolt in the city, and for murder.'),
  ('f7545658-d443-522b-a6b0-0346e97176ae', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 20, 20, 'Then Pilate spoke to them again, wanting to release Jesus,'),
  ('8e8e8c17-8ba4-5912-ad03-de4cb8961237', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 21, 21, 'but they shouted, saying, "Crucify! Crucify him!"'),
  ('20b2689e-6572-5c3d-a4fb-22ad1066831e', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 22, 22, 'He said to them the third time, "Why? What evil has this man done? I have found no capital crime in him. I will therefore chastise him and release him."'),
  ('4f2f59c8-e8f8-5815-a997-3f04bfd3600f', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 23, 23, 'But they were urgent with loud voices, asking that he might be crucified. Their voices and the voices of the chief priests prevailed.'),
  ('f4f40074-afcc-5e87-a5fb-00f6cc0c6676', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 24, 24, 'Pilate decreed that what they asked for should be done.'),
  ('99880f97-0ef5-52b2-aaf2-3c37bcf00d13', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 25, 25, 'He released him who had been thrown into prison for insurrection and murder, for whom they asked, but he delivered Jesus up to their will.'),
  ('b3bf1dd0-764c-56c8-a839-cc43119f4e59', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 26, 26, 'When they led him away, they grabbed one Simon of Cyrene, coming from the country, and laid on him the cross, to carry it after Jesus.'),
  ('72c7c02f-a317-5f92-a568-cd68a4d9e259', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 27, 27, 'A great multitude of the people followed him, including women who also mourned and lamented him.'),
  ('15b64f57-a24c-5759-afe6-934dfa8a4542', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 28, 28, 'But Jesus, turning to them, said, "Daughters of Jerusalem, don''t weep for me, but weep for yourselves and for your children.'),
  ('228c4bee-1247-5588-a28c-c2cdf053047e', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 29, 29, 'For behold, the days are coming in which they will say, ''Blessed are the barren, the wombs that never bore, and the breasts that never nursed.'''),
  ('c1f6c6c4-4ffe-5723-a102-def7c157dd14', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 30, 30, 'Then they will begin to tell the mountains, ''Fall on us!'' and tell the hills, ''Cover us.'''),
  ('e01b067c-776f-55af-ab46-181fc936282c', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 31, 31, 'For if they do these things in the green tree, what will be done in the dry?"'),
  ('bb2d8ccc-7268-5f74-a174-fc4cc6cfc830', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 32, 32, 'There were also others, two criminals, led with him to be put to death.'),
  ('b88d3b85-c6e4-5c42-a4c0-1220d7a26295', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 33, 33, 'When they came to the place that is called The Skull, they crucified him there with the criminals, one on the right and the other on the left.'),
  ('73a4985e-3ab0-502b-a101-a52b968456a4', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 34, 34, 'Jesus said, "Father, forgive them, for they don''t know what they are doing." Dividing his garments among them, they cast lots.'),
  ('d4db51b2-6508-5caf-a1d7-32feccb39e44', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 35, 35, 'The people stood watching. The rulers with them also scoffed at him, saying, "He saved others. Let him save himself, if this is the Christ of God, his chosen one!"'),
  ('a4f8f56a-af6e-54ec-a079-5be35e9eb8c9', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 36, 36, 'The soldiers also mocked him, coming to him and offering him vinegar,'),
  ('1cc1a434-cb7a-557e-ab31-2652404f66a0', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 37, 37, 'and saying, "If you are the King of the Jews, save yourself!"'),
  ('8d183aa8-54db-5ae4-a279-06a1063e6859', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 38, 38, 'An inscription was also written over him in letters of Greek, Latin, and Hebrew: "THIS IS THE KING OF THE JEWS."'),
  ('bf55f2ae-9f57-524a-acf5-554b3726e22c', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 39, 39, 'One of the criminals who was hanged insulted him, saying, "If you are the Christ, save yourself and us!"'),
  ('23e610a6-0bac-5d37-a4ff-41550723a54b', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 40, 40, 'But the other answered, and rebuking him said, "Don''t you even fear God, seeing you are under the same condemnation?'),
  ('0c599e14-33b0-53a2-adc9-3c91bc0fc7e3', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 41, 41, 'And we indeed justly, for we receive the due reward for our deeds, but this man has done nothing wrong."'),
  ('950d8009-8c4b-533e-aaa4-071f46abd674', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 42, 42, 'He said to Jesus, "Lord, remember me when you come into your Kingdom."'),
  ('378a41c0-8295-54de-aec7-6ab1c9d344bf', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 43, 43, 'Jesus said to him, "Assuredly I tell you, today you will be with me in Paradise."'),
  ('42635ef1-f742-572b-aa15-af4d0da5a038', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 44, 44, 'It was now about the sixth hour, and darkness came over the whole land until the ninth hour.'),
  ('3f16f31f-7ab5-5c5c-a93b-3df24d13e9d3', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 45, 45, 'The sun was darkened, and the veil of the temple was torn in two.'),
  ('338b54cf-d252-576c-afa6-f3e1e6bbb15c', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 46, 46, 'Jesus, crying with a loud voice, said, "Father, into your hands I commit my spirit!" Having said this, he breathed his last.'),
  ('d3ef13f9-30ba-583f-a1c9-4850973ec9c1', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 47, 47, 'When the centurion saw what was done, he glorified God, saying, "Certainly this was a righteous man."'),
  ('2e26ede8-8f79-590f-a65d-710c3273d435', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 48, 48, 'All the multitudes that came together to see this, when they saw the things that were done, returned home beating their breasts.'),
  ('013f1c36-6dee-5f2d-ad02-d1dab14236f1', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 49, 49, 'All his acquaintances, and the women who followed with him from Galilee, stood at a distance, watching these things.'),
  ('8b5d1da1-aca1-5e8d-aead-932747ecd367', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 50, 50, 'Behold, a man named Joseph, who was a member of the council, a good and righteous man'),
  ('9b561a8e-45bc-513a-a33c-97244e8bdefd', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 51, 51, '(he had not consented to their counsel and deed), from Arimathaea, a city of the Jews, who was also waiting for the Kingdom of God:'),
  ('9cdbb97c-db43-5eee-aa39-f66b49e21da0', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 52, 52, 'this man went to Pilate, and asked for Jesus'' body.'),
  ('eef6d83c-41a2-51f9-a726-02738545e90c', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 53, 53, 'He took it down, and wrapped it in a linen cloth, and laid him in a tomb that was cut in stone, where no one had ever been laid.'),
  ('5112f3e1-486c-54f9-afb5-4b5b6279742f', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 54, 54, 'It was the day of the Preparation, and the Sabbath was drawing near.'),
  ('f690fc59-a843-5988-ae7f-177e7d64acb2', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 55, 55, 'The women, who had come with him out of Galilee, followed after, and saw the tomb, and how his body was laid.'),
  ('5091f7c9-35c0-5a13-a71e-72ebc2a4c6a9', '775b6f40-4628-50ff-a4ea-1f67ce8e5624', NULL, 56, 56, 'They returned, and prepared spices and ointments. On the Sabbath they rested according to the commandment.'),
  ('606bb4a2-391d-52e8-a1fb-eb123073eb90', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 1, 1, 'But on the first day of the week, at early dawn, they and some others came to the tomb, bringing the spices which they had prepared.'),
  ('7858c235-55fe-56dd-acac-33bb0b3f2432', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 2, 2, 'They found the stone rolled away from the tomb.'),
  ('2aae8dae-2e68-5ea4-a06e-5f7e61c2a1fc', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 3, 3, 'They entered in, and didn''t find the Lord Jesus'' body.'),
  ('0712d284-0298-51c3-a9fe-0794d5611b18', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 4, 4, 'It happened, while they were greatly perplexed about this, behold, two men stood by them in dazzling clothing.'),
  ('7aae5f43-2c37-59cb-ae38-fbdcdfa6b6b9', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 5, 5, 'Becoming terrified, they bowed their faces down to the earth. They said to them, "Why do you seek the living among the dead?'),
  ('3468d6dc-2074-5b04-af60-ea0373d1b67c', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 6, 6, 'He isn''t here, but is risen. Remember what he told you when he was still in Galilee,'),
  ('718a1730-3e94-57dd-ac0e-51df6d243313', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 7, 7, 'saying that the Son of Man must be delivered up into the hands of sinful men, and be crucified, and the third day rise again?"'),
  ('31239378-bf8a-568d-a756-463f2f9a8045', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 8, 8, 'They remembered his words,'),
  ('a9d655e7-ca19-503a-a484-4f63b383d1b2', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 9, 9, 'returned from the tomb, and told all these things to the eleven, and to all the rest.'),
  ('561db38b-3827-5586-a4ef-f20dd4020ba7', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 10, 10, 'Now they were Mary Magdalene, Joanna, and Mary the mother of James. The other women with them told these things to the apostles.'),
  ('d032dd86-638d-5c6e-aaaa-3bc0557ba0a3', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 11, 11, 'These words seemed to them to be nonsense, and they didn''t believe them.'),
  ('aa2c7aa3-6148-5f7c-ac59-558dd93166d9', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 12, 12, 'But Peter got up and ran to the tomb. Stooping and looking in, he saw the strips of linen lying by themselves, and he departed to his home, wondering what had happened.'),
  ('07c10bc0-6ded-5518-ab98-d4e77128d8f4', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 13, 13, 'Behold, two of them were going that very day to a village named Emmaus, which was sixty stadia from Jerusalem.'),
  ('805d501c-55d8-5558-a9cd-44b7bccf09e6', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 14, 14, 'They talked with each other about all of these things which had happened.'),
  ('e2c58006-7e42-51e0-a109-fa786262721e', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 15, 15, 'It happened, while they talked and questioned together, that Jesus himself came near, and went with them.'),
  ('f3ebc574-22f6-5ffc-ab6d-4d20128d1f0b', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 16, 16, 'But their eyes were kept from recognizing him.'),
  ('2d564aa5-fc42-53b5-ae28-7d9bc372b3e5', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 17, 17, 'He said to them, "What are you talking about as you walk, and are sad?"'),
  ('76a5bc71-d630-5ae1-a50b-36535176d83a', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 18, 18, 'One of them, named Cleopas, answered him, "Are you the only stranger in Jerusalem who doesn''t know the things which have happened there in these days?"'),
  ('07cad01f-9ad3-5870-abc3-13a1da84bb3c', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 19, 19, 'He said to them, "What things?" They said to him, "The things concerning Jesus, the Nazarene, who was a prophet mighty in deed and word before God and all the people;'),
  ('1d302e42-7272-5814-a48b-f5cdd1050b42', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 20, 20, 'and how the chief priests and our rulers delivered him up to be condemned to death, and crucified him.'),
  ('e93ed738-f269-5b04-a4ee-81b0a91b1f42', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 21, 21, 'But we were hoping that it was he who would redeem Israel. Yes, and besides all this, it is now the third day since these things happened.'),
  ('9ef940b5-0d4d-5d74-a192-a59878824539', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 22, 22, 'Also, certain women of our company amazed us, having arrived early at the tomb;'),
  ('de7d7bd5-dd10-5b2a-a545-07a90556adb9', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 23, 23, 'and when they didn''t find his body, they came saying that they had also seen a vision of angels, who said that he was alive.'),
  ('66f901ca-1394-5300-ab4d-3c4fb08dcfbc', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 24, 24, 'Some of us went to the tomb, and found it just like the women had said, but they didn''t see him."'),
  ('f25f8e37-c3b5-53ef-a48f-61b61af49cb8', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 25, 25, 'He said to them, "Foolish men, and slow of heart to believe in all that the prophets have spoken!'),
  ('e624ed86-aa21-5557-aad5-3539b8b0eb7e', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 26, 26, 'Didn''t the Christ have to suffer these things and to enter into his glory?"'),
  ('98e5e21f-025c-5b98-a8b7-d19856573d07', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 27, 27, 'Beginning from Moses and from all the prophets, he explained to them in all the Scriptures the things concerning himself.'),
  ('5e6ac23b-1e74-5498-a567-5c1eb22ffce8', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 28, 28, 'They drew near to the village, where they were going, and he acted like he would go further.'),
  ('d8cc608d-c1b0-5e99-a12e-51b2c3bd241b', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 29, 29, 'They urged him, saying, "Stay with us, for it is almost evening, and the day is almost over." He went in to stay with them.'),
  ('b6108f7a-ac5c-5142-abee-1bdfddba215b', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 30, 30, 'It happened, that when he had sat down at the table with them, he took the bread and gave thanks. Breaking it, he gave to them.'),
  ('e683a8fc-1920-506a-a4c2-33c5a7faf68e', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 31, 31, 'Their eyes were opened, and they recognized him, and he vanished out of their sight.'),
  ('47c6ea77-8b2a-5e8e-a327-6481a318ceb1', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 32, 32, 'They said one to another, "Weren''t our hearts burning within us, while he spoke to us along the way, and while he opened the Scriptures to us?"'),
  ('74f98165-e04f-521e-a655-00f92a22ded4', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 33, 33, 'They rose up that very hour, returned to Jerusalem, and found the eleven gathered together, and those who were with them,'),
  ('d29081b4-7050-59be-a61a-9242719ef1b6', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 34, 34, 'saying, "The Lord is risen indeed, and has appeared to Simon!"'),
  ('c81fcaf1-5c8e-5563-aa04-081ab68148f0', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 35, 35, 'They related the things that happened along the way, and how he was recognized by them in the breaking of the bread.'),
  ('40f86b1f-ad85-5a01-a912-60e64d735625', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 36, 36, 'As they said these things, Jesus himself stood among them, and said to them, "Peace be to you."'),
  ('2c0502d7-4c98-5884-a063-553496b5b3a7', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 37, 37, 'But they were terrified and filled with fear, and supposed that they had seen a spirit.'),
  ('43574470-cdaa-5031-aa99-351fce726332', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 38, 38, 'He said to them, "Why are you troubled? Why do doubts arise in your hearts?'),
  ('d6812964-5c22-5452-abc0-20bc09693d75', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 39, 39, 'See my hands and my feet, that it is truly me. Touch me and see, for a spirit doesn''t have flesh and bones, as you see that I have."'),
  ('5dca6146-53d3-59a9-a3ec-691590462285', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 40, 40, 'When he had said this, he showed them his hands and his feet.'),
  ('ad94f439-8703-54cf-ab2a-2a4966bb1ee6', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 41, 41, 'While they still didn''t believe for joy, and wondered, he said to them, "Do you have anything here to eat?"'),
  ('57684ef1-9fcc-5b45-a9d2-e685c11f4137', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 42, 42, 'They gave him a piece of a broiled fish and some honeycomb.'),
  ('9f021e95-152c-53f2-ac72-ba41351d9fe8', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 43, 43, 'He took them, and ate in front of them.'),
  ('5182433f-ce0e-5614-a2d4-68d756e9993a', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 44, 44, 'He said to them, "This is what I told you, while I was still with you, that all things which are written in the law of Moses, the prophets, and the psalms, concerning me must be fulfilled."'),
  ('9ad3dbe5-41ab-54ee-afac-5164b74db0a9', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 45, 45, 'Then he opened their minds, that they might understand the Scriptures.'),
  ('6995b463-8a4c-5c8b-acec-b7a290f69041', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 46, 46, 'He said to them, "Thus it is written, and thus it was necessary for the Christ to suffer and to rise from the dead the third day,'),
  ('a09321bb-3998-5410-aa46-c5cefdd0cca3', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 47, 47, 'and that repentance and remission of sins should be preached in his name to all the nations, beginning at Jerusalem.'),
  ('b3335fdd-82b4-5596-ae11-722464c19251', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 48, 48, 'You are witnesses of these things.'),
  ('8386b50a-a2e4-5662-a34e-55ab0b5efd59', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 49, 49, 'Behold, I send forth the promise of my Father on you. But wait in the city of Jerusalem until you are clothed with power from on high."'),
  ('92f1c2bc-78d2-5a6f-a16f-afdb624e2a32', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 50, 50, 'He led them out as far as Bethany, and he lifted up his hands, and blessed them.'),
  ('6d618dcf-2aa8-569c-a3e6-8c26c218b414', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 51, 51, 'It happened, while he blessed them, that he withdrew from them, and was carried up into heaven.'),
  ('a7c42964-b250-5f20-afcb-b271f04e4646', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 52, 52, 'They worshiped him, and returned to Jerusalem with great joy,'),
  ('d93b24ea-1f90-5f13-afb9-dbcb9d9b21b7', '5836d36d-b569-5885-a55d-62fd3ff4b80e', NULL, 53, 53, 'and were continually in the temple, praising and blessing God. Amen.'),
  ('10ff1de1-5be8-5fac-a869-07f41bc39359', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 1, 1, 'In the beginning was the Word, and the Word was with God, and the Word was God.'),
  ('98be5653-3d30-524b-a58b-45d10bf8bcff', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 2, 2, 'The same was in the beginning with God.'),
  ('4697ca75-5f50-56d7-a958-22aa929eb1fa', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 3, 3, 'All things were made through him. Without him was not anything made that has been made.'),
  ('c3be1d86-f735-5ac0-a3de-6acf03f09335', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 4, 4, 'In him was life, and the life was the light of men.'),
  ('eac23523-2299-5dbb-a5f4-d906a930571f', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 5, 5, 'The light shines in the darkness, and the darkness hasn''t overcome it.'),
  ('6639e582-7522-554f-a305-62eb66784fd3', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 6, 6, 'There came a man, sent from God, whose name was John.'),
  ('beef233c-6a87-500e-a417-9f6e45b13ccf', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 7, 7, 'The same came as a witness, that he might testify about the light, that all might believe through him.'),
  ('9d726ae5-4898-5164-ae60-6c9287f2d66e', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 8, 8, 'He was not the light, but was sent that he might testify about the light.'),
  ('4d3a788f-cdb8-5fc9-ae4a-87b83e1bd712', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 9, 9, 'The true light that enlightens everyone was coming into the world.'),
  ('a60dd4eb-49e8-59b5-a079-5b69b645a546', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 10, 10, 'He was in the world, and the world was made through him, and the world didn''t recognize him.'),
  ('6bfc3bd9-60c3-54d0-a454-62bca49aadec', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 11, 11, 'He came to his own, and those who were his own didn''t receive him.'),
  ('54913d42-3b16-52af-aafa-cb0a5cc37c27', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 12, 12, 'But as many as received him, to them he gave the right to become God''s children, to those who believe in his name:'),
  ('bbaaedf9-1a53-5aa0-a4a0-7980644f82f3', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 13, 13, 'who were born not of blood, nor of the will of the flesh, nor of the will of man, but of God.'),
  ('42d7456a-8d0b-5a6b-ab5a-36b5c039765c', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 14, 14, 'The Word became flesh, and lived among us. We saw his glory, such glory as of the one and only Son of the Father, full of grace and truth.'),
  ('28cf0fd4-d810-506c-aa79-8160a34895d8', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 15, 15, 'John testified about him. He cried out, saying, "This was he of whom I said, ''He who comes after me has surpassed me, for he was before me.''"'),
  ('fcc13742-9c40-575c-a060-349fb569c5a8', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 16, 16, 'From his fullness we all received grace upon grace.'),
  ('b4e05eae-bb2e-5b89-a0a5-77c8783fbe2c', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 17, 17, 'For the law was given through Moses. Grace and truth were realized through Jesus Christ.'),
  ('8e64fe3a-c525-5dd9-a268-f50febd0283b', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 18, 18, 'No one has seen God at any time. The one and only Son, who is in the bosom of the Father, he has declared him.'),
  ('b8088949-be3d-5aa6-ac2d-5fc19824e992', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 19, 19, 'This is John''s testimony, when the Jews sent priests and Levites from Jerusalem to ask him, "Who are you?"'),
  ('15fdf60f-a17e-539c-a63c-533309c1587f', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 20, 20, 'He declared, and didn''t deny, but he declared, "I am not the Christ."'),
  ('1e4da54a-cedc-54d5-a821-b3f6e91d2611', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 21, 21, 'They asked him, "What then? Are you Elijah?" He said, "I am not." "Are you the prophet?" He answered, "No."'),
  ('df8b622c-584d-5fb9-a0df-b3188dee15f6', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 22, 22, 'They said therefore to him, "Who are you? Give us an answer to take back to those who sent us. What do you say about yourself?"'),
  ('38d17aa5-aae8-5f1c-a463-a818985c8409', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 23, 23, 'He said, "I am the voice of one crying in the wilderness, ''Make straight the way of the Lord,'' as Isaiah the prophet said."'),
  ('426b31e5-8987-52be-ab16-e75d2a747712', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 24, 24, 'The ones who had been sent were from the Pharisees.'),
  ('8b3a1cb0-7623-536c-a84a-cae09ec624a9', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 25, 25, 'They asked him, "Why then do you baptize, if you are not the Christ, nor Elijah, nor the prophet?"'),
  ('3755d7e8-54d4-514a-adb4-31c0b0255212', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 26, 26, 'John answered them, "I baptize in water, but among you stands one whom you don''t know.'),
  ('852073b6-8a58-512d-ad19-5077b098461b', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 27, 27, 'He is the one who comes after me, who is preferred before me, whose sandal strap I''m not worthy to loosen."'),
  ('a3729c9d-2c61-5544-a847-de7890df7948', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 28, 28, 'These things were done in Bethany beyond the Jordan, where John was baptizing.'),
  ('bb78c190-bf62-52fa-af47-41213f4d0c41', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 29, 29, 'The next day, he saw Jesus coming to him, and said, "Behold, the Lamb of God, who takes away the sin of the world!'),
  ('52748f48-b0d3-56c6-ad9b-0a0e93f0eb7f', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 30, 30, 'This is he of whom I said, ''After me comes a man who is preferred before me, for he was before me.'''),
  ('df34c4be-54bb-5f1a-a4cf-89f4cb52d187', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 31, 31, 'I didn''t know him, but for this reason I came baptizing in water: that he would be revealed to Israel."'),
  ('fb246e94-7b8c-55cf-acfc-60f099a6cd08', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 32, 32, 'John testified, saying, "I have seen the Spirit descending like a dove out of heaven, and it remained on him.'),
  ('a39b7c5a-0c63-5d42-ab5f-8c32044259e3', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 33, 33, 'I didn''t recognize him, but he who sent me to baptize in water, he said to me, ''On whomever you will see the Spirit descending, and remaining on him, the same is he who baptizes in the Holy Spirit.'''),
  ('fce6a936-52f1-50e5-a704-5e9d406ef6c0', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 34, 34, 'I have seen, and have testified that this is the Son of God."'),
  ('74f6c098-7681-5adf-a0ee-a5e6a90a7d4e', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 35, 35, 'Again, the next day, John was standing with two of his disciples,'),
  ('c1e8f547-efd1-5c1e-a360-51b59d28b67f', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 36, 36, 'and he looked at Jesus as he walked, and said, "Behold, the Lamb of God!"'),
  ('4817ed5e-3895-5feb-a352-c707d35118e7', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 37, 37, 'The two disciples heard him speak, and they followed Jesus.'),
  ('a7bf4122-dcd0-5c24-a8d4-b34f8e44fdc0', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 38, 38, 'Jesus turned, and saw them following, and said to them, "What are you looking for?" They said to him, "Rabbi" (which is to say, being interpreted, Teacher), "where are you staying?"'),
  ('1b0982a6-5253-5fa7-a100-cf71a92d1e3f', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 39, 39, 'He said to them, "Come, and see." They came and saw where he was staying, and they stayed with him that day. It was about the tenth hour.'),
  ('bc5b2139-6518-5408-aee4-c6bbcb14e872', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 40, 40, 'One of the two who heard John, and followed him, was Andrew, Simon Peter''s brother.'),
  ('be7f2429-6e55-5a81-a97e-89d1f12b69ae', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 41, 41, 'He first found his own brother, Simon, and said to him, "We have found the Messiah!" (which is, being interpreted, Christ).'),
  ('c45f7db2-f325-5445-a9da-1837f18c1a3e', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 42, 42, 'He brought him to Jesus. Jesus looked at him, and said, "You are Simon the son of Jonah. You shall be called Cephas" (which is by interpretation, Peter).'),
  ('caccfad1-8f87-535d-ad63-41333f4671ae', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 43, 43, 'On the next day, he was determined to go out into Galilee, and he found Philip. Jesus said to him, "Follow me."'),
  ('ecb3c3b8-850d-51f1-a569-4cdf9bc3afe4', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 44, 44, 'Now Philip was from Bethsaida, of the city of Andrew and Peter.'),
  ('d7d0447e-5cd2-5b85-a571-ce9afd97ebe0', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 45, 45, 'Philip found Nathanael, and said to him, "We have found him, of whom Moses in the law, and the prophets, wrote: Jesus of Nazareth, the son of Joseph."'),
  ('361b8faf-a1e4-5d09-a10d-2aa7cff0a4ee', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 46, 46, 'Nathanael said to him, "Can any good thing come out of Nazareth?" Philip said to him, "Come and see."'),
  ('0cc878f5-5de1-594b-ac73-206b63e827b7', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 47, 47, 'Jesus saw Nathanael coming to him, and said about him, "Behold, an Israelite indeed, in whom is no deceit!"'),
  ('a2773170-8720-581f-a06b-2c6eea6893c5', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 48, 48, 'Nathanael said to him, "How do you know me?" Jesus answered him, "Before Philip called you, when you were under the fig tree, I saw you."'),
  ('fa33d0d4-1c7e-5fd7-a122-77fcab018b62', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 49, 49, 'Nathanael answered him, "Rabbi, you are the Son of God! You are King of Israel!"'),
  ('930a45d6-9929-5b39-a392-0115f75c0b8c', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 50, 50, 'Jesus answered him, "Because I told you, ''I saw you underneath the fig tree,'' do you believe? You will see greater things than these!"'),
  ('c00577f7-a64a-5ac7-a0b2-5557d09d3a23', 'dd8859dc-5007-591a-a34b-db9004779223', NULL, 51, 51, 'He said to him, "Most certainly, I tell you, hereafter you will see heaven opened, and the angels of God ascending and descending on the Son of Man."'),
  ('6008e3f4-5fc0-55f9-a664-b5426be913d8', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 1, 1, 'The third day, there was a marriage in Cana of Galilee. Jesus'' mother was there.'),
  ('446ae017-c0e5-5823-a281-c709d506493f', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 2, 2, 'Jesus also was invited, with his disciples, to the marriage.'),
  ('0c9885e7-d8e1-5a8a-a498-7579a1eceb67', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 3, 3, 'When the wine ran out, Jesus'' mother said to him, "They have no wine."'),
  ('1612d73f-0a4f-5538-a5f9-ae7f741b6f75', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 4, 4, 'Jesus said to her, "Woman, what does that have to do with you and me? My hour has not yet come."'),
  ('171b4093-2a46-524d-a096-83f1daecd3e8', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 5, 5, 'His mother said to the servants, "Whatever he says to you, do it."'),
  ('ad030f72-36b7-554a-a50c-e366c7bb79c2', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 6, 6, 'Now there were six water pots of stone set there after the Jews'' way of purifying, containing two or three metretes apiece.'),
  ('23be345c-199a-5093-af61-3c0cd491ee63', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 7, 7, 'Jesus said to them, "Fill the water pots with water." They filled them up to the brim.'),
  ('aa496f80-7e32-5c98-ad9f-3973e708a618', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 8, 8, 'He said to them, "Now draw some out, and take it to the ruler of the feast." So they took it.'),
  ('10e56d20-6063-5c48-a95d-b1360aca5f0c', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 9, 9, 'When the ruler of the feast tasted the water now become wine, and didn''t know where it came from (but the servants who had drawn the water knew), the ruler of the feast called the bridegroom,'),
  ('43c39775-1681-5a7e-a21b-cfc228ba2cc8', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 10, 10, 'and said to him, "Everyone serves the good wine first, and when the guests have drunk freely, then that which is worse. You have kept the good wine until now!"'),
  ('ac821612-896a-5b66-a0fe-3399531d2eac', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 11, 11, 'This beginning of his signs Jesus did in Cana of Galilee, and revealed his glory; and his disciples believed in him.'),
  ('0dd1ba3d-6f05-59f2-a80b-22b3b5ca6133', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 12, 12, 'After this, he went down to Capernaum, he, and his mother, his brothers, and his disciples; and they stayed there a few days.'),
  ('92271931-5243-5718-a82e-2154ab7bac8e', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 13, 13, 'The Passover of the Jews was at hand, and Jesus went up to Jerusalem.'),
  ('e5a30955-58f6-503e-a739-f2d1e34c16ff', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 14, 14, 'He found in the temple those who sold oxen, sheep, and doves, and the changers of money sitting.'),
  ('008e9b0b-0ddb-5826-ad14-45c8740d1b03', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 15, 15, 'He made a whip of cords, and threw all out of the temple, both the sheep and the oxen; and he poured out the changers'' money, and overthrew their tables.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('95efcc86-bfff-5c9c-a1e8-91128480f16d', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 16, 16, 'To those who sold the doves, he said, "Take these things out of here! Don''t make my Father''s house a marketplace!"'),
  ('df96a162-0e87-50ee-afba-92074ea2eea3', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 17, 17, 'His disciples remembered that it was written, "Zeal for your house will eat me up."'),
  ('42ff892d-2075-54f3-aebc-c911968412a5', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 18, 18, 'The Jews therefore answered him, "What sign do you show us, seeing that you do these things?"'),
  ('5469e497-2f59-5601-a3a3-cbd064d4452a', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 19, 19, 'Jesus answered them, "Destroy this temple, and in three days I will raise it up."'),
  ('0d602618-b001-5b67-a6ed-64e0e347b1b3', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 20, 20, 'The Jews therefore said, "It took forty-six years to build this temple! Will you raise it up in three days?"'),
  ('37f50bff-9c38-55ed-a94c-108d736e298f', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 21, 21, 'But he spoke of the temple of his body.'),
  ('bfc518e2-3313-5642-a5da-8a5080767ce3', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 22, 22, 'When therefore he was raised from the dead, his disciples remembered that he said this, and they believed the Scripture, and the word which Jesus had said.'),
  ('ec81800d-64f7-5fdd-aea6-fd2286bd3daf', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 23, 23, 'Now when he was in Jerusalem at the Passover, during the feast, many believed in his name, observing his signs which he did.'),
  ('7ed3137b-06b7-5dbf-a990-dd62baadf262', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 24, 24, 'But Jesus didn''t trust himself to them, because he knew everyone,'),
  ('9ced3292-39d0-5972-a818-ff8b8036cf59', '574ae4ee-a43e-5d32-a66e-b1b6f960a1b8', NULL, 25, 25, 'and because he didn''t need for anyone to testify concerning man; for he himself knew what was in man.'),
  ('4a2893ec-e12a-5a14-a779-a072605bf29d', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 1, 1, 'Now there was a man of the Pharisees named Nicodemus, a ruler of the Jews.'),
  ('c84e3e3f-3a09-51b0-a27a-729acf622bad', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 2, 2, 'The same came to him by night, and said to him, "Rabbi, we know that you are a teacher come from God, for no one can do these signs that you do, unless God is with him."'),
  ('f6377493-d6eb-5f9a-ab43-ed951b7a0df4', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 3, 3, 'Jesus answered him, "Most certainly, I tell you, unless one is born anew, he can''t see the Kingdom of God."'),
  ('604e0136-53b7-5dbb-add6-3c351bf890aa', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 4, 4, 'Nicodemus said to him, "How can a man be born when he is old? Can he enter a second time into his mother''s womb, and be born?"'),
  ('26a4387a-140b-5344-a2ae-4ce6cb4ff7b2', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 5, 5, 'Jesus answered, "Most certainly I tell you, unless one is born of water and spirit, he can''t enter into the Kingdom of God!'),
  ('6bea4584-31ee-588c-a8f4-3b539b725fb9', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 6, 6, 'That which is born of the flesh is flesh. That which is born of the Spirit is spirit.'),
  ('e4a5e830-a2ea-5bdf-a96d-a8ee3af41072', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 7, 7, 'Don''t marvel that I said to you, ''You must be born anew.'''),
  ('c646ea2f-809e-56bc-aa40-930953fad333', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 8, 8, 'The wind blows where it wants to, and you hear its sound, but don''t know where it comes from and where it is going. So is everyone who is born of the Spirit."'),
  ('e671d8c4-3745-5ea8-a63c-81bf61472998', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 9, 9, 'Nicodemus answered him, "How can these things be?"'),
  ('78823b17-8c88-54b7-a465-2a7da68c1f4f', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 10, 10, 'Jesus answered him, "Are you the teacher of Israel, and don''t understand these things?'),
  ('a88d24ff-3fa8-5940-a372-705d33aef3c5', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 11, 11, 'Most certainly I tell you, we speak that which we know, and testify of that which we have seen, and you don''t receive our witness.'),
  ('45d0c1d0-7011-5caf-a227-4f66891e73d5', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 12, 12, 'If I told you earthly things and you don''t believe, how will you believe if I tell you heavenly things?'),
  ('d7bb26cf-0360-5107-a2f7-bcaedd598164', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 13, 13, 'No one has ascended into heaven, but he who descended out of heaven, the Son of Man, who is in heaven.'),
  ('d115165d-191f-5cb5-a3d2-8543a889d90c', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 14, 14, 'As Moses lifted up the serpent in the wilderness, even so must the Son of Man be lifted up,'),
  ('1e1727cd-4c43-5727-a65e-a12a06bd50e5', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 15, 15, 'that whoever believes in him should not perish, but have eternal life.'),
  ('3dd2b9dd-c874-5c0a-a064-44b4d2204459', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 16, 16, 'For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.'),
  ('73befc6a-4605-5a1c-ab66-4de193481763', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 17, 17, 'For God didn''t send his Son into the world to judge the world, but that the world should be saved through him.'),
  ('afa09ae9-b5ae-59b8-a578-336bf70204cf', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 18, 18, 'He who believes in him is not judged. He who doesn''t believe has been judged already, because he has not believed in the name of the one and only Son of God.'),
  ('f5559175-6ecb-5c94-a3cc-d6023ce922ca', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 19, 19, 'This is the judgment, that the light has come into the world, and men loved the darkness rather than the light; for their works were evil.'),
  ('95070499-e056-57f0-a37d-1e2291f5453a', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 20, 20, 'For everyone who does evil hates the light, and doesn''t come to the light, lest his works would be exposed.'),
  ('c5337b1b-8ec8-528e-abd7-e70055330ac1', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 21, 21, 'But he who does the truth comes to the light, that his works may be revealed, that they have been done in God."'),
  ('05c4a3a7-b792-543d-a920-2a9bff8f2ca0', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 22, 22, 'After these things, Jesus came with his disciples into the land of Judea. He stayed there with them, and baptized.'),
  ('887b78e7-dcc2-593c-a11c-8975ecf98b17', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 23, 23, 'John also was baptizing in Enon near Salim, because there was much water there. They came, and were baptized.'),
  ('6dfedd18-e59e-58a0-af86-de3d5fbd6ddc', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 24, 24, 'For John was not yet thrown into prison.'),
  ('a5c75e92-f110-52f1-a468-9e6434cd0055', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 25, 25, 'There arose therefore a questioning on the part of John''s disciples with some Jews about purification.'),
  ('29c3fa9a-981e-5d61-a58b-c1e02d0d9a2b', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 26, 26, 'They came to John, and said to him, "Rabbi, he who was with you beyond the Jordan, to whom you have testified, behold, the same baptizes, and everyone is coming to him."'),
  ('3750bbd2-3a72-573d-a3a4-1be6022ffea8', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 27, 27, 'John answered, "A man can receive nothing, unless it has been given him from heaven.'),
  ('63162ce6-8384-516c-a308-a221650eede7', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 28, 28, 'You yourselves testify that I said, ''I am not the Christ,'' but, ''I have been sent before him.'''),
  ('06db096d-8ed6-540c-a780-f9f9d6637e77', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 29, 29, 'He who has the bride is the bridegroom; but the friend of the bridegroom, who stands and hears him, rejoices greatly because of the bridegroom''s voice. This, my joy, therefore is made full.'),
  ('06c4feff-f449-5188-a15a-7e534e9e3c8f', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 30, 30, 'He must increase, but I must decrease.'),
  ('a60849b1-3824-5513-a97f-533ab16759d8', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 31, 31, 'He who comes from above is above all. He who is from the Earth belongs to the Earth, and speaks of the Earth. He who comes from heaven is above all.'),
  ('833e9243-5f8c-59ef-ae34-33cb6ffcee39', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 32, 32, 'What he has seen and heard, of that he testifies; and no one receives his witness.'),
  ('dfe2a428-f492-5d8f-a175-a23783a5e797', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 33, 33, 'He who has received his witness has set his seal to this, that God is true.'),
  ('869c93f8-c62e-539b-a65a-692121d96823', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 34, 34, 'For he whom God has sent speaks the words of God; for God gives the Spirit without measure.'),
  ('06cbf77a-9b17-5497-abb6-eeec1a18aaf8', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 35, 35, 'The Father loves the Son, and has given all things into his hand.'),
  ('c0dffa3a-d7cf-59f8-a877-999bcd0092d4', '15c7724e-9447-524f-aadc-ed700df642fb', NULL, 36, 36, 'One who believes in the Son has eternal life, but one who disobeys the Son won''t see life, but the wrath of God remains on him."'),
  ('067bf9ac-de07-508f-a35e-3610029c295e', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 1, 1, 'Therefore when the Lord knew that the Pharisees had heard that Jesus was making and baptizing more disciples than John'),
  ('0c808a83-d842-501b-afa5-571d038830b3', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 2, 2, '(although Jesus himself didn''t baptize, but his disciples),'),
  ('53c91529-ff25-5150-a9e1-5409990af26f', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 3, 3, 'he left Judea, and departed into Galilee.'),
  ('a6646f79-26f5-55f2-acf1-15b2fd29bd3f', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 4, 4, 'He needed to pass through Samaria.'),
  ('b12999ca-77ed-5094-ad83-7ae4a6f83351', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 5, 5, 'So he came to a city of Samaria, called Sychar, near the parcel of ground that Jacob gave to his son, Joseph.'),
  ('681e6d18-71a0-54e7-a76a-c1d3d07bb137', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 6, 6, 'Jacob''s well was there. Jesus therefore, being tired from his journey, sat down by the well. It was about the sixth hour.'),
  ('4103e96b-2695-58d8-a5ce-332553391124', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 7, 7, 'A woman of Samaria came to draw water. Jesus said to her, "Give me a drink."'),
  ('f7360640-9df9-5939-a1e4-76e50df3b3ee', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 8, 8, 'For his disciples had gone away into the city to buy food.'),
  ('29ce2788-2bbd-5311-ae6f-90dae804c49b', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 9, 9, 'The Samaritan woman therefore said to him, "How is it that you, being a Jew, ask for a drink from me, a Samaritan woman?" (For Jews have no dealings with Samaritans.)'),
  ('a62e68d3-0e12-5cae-ac3f-421aeed53be0', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 10, 10, 'Jesus answered her, "If you knew the gift of God, and who it is who says to you, ''Give me a drink,'' you would have asked him, and he would have given you living water."'),
  ('e06d541e-b4ea-51e6-a5b5-7f81676a5888', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 11, 11, 'The woman said to him, "Sir, you have nothing to draw with, and the well is deep. From where then have you that living water?'),
  ('5804761f-9775-5cad-abfb-27e41aed7bdc', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 12, 12, 'Are you greater than our father, Jacob, who gave us the well, and drank of it himself, as did his children, and his livestock?"'),
  ('9dcc0e56-d3cb-5843-a048-13531912c761', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 13, 13, 'Jesus answered her, "Everyone who drinks of this water will thirst again,'),
  ('ccf7412d-ef0c-5a3d-a5f1-31aef15f5fdd', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 14, 14, 'but whoever drinks of the water that I will give him will never thirst again; but the water that I will give him will become in him a well of water springing up to eternal life."'),
  ('964ed072-e350-5b95-a331-cbb2241fb63f', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 15, 15, 'The woman said to him, "Sir, give me this water, so that I don''t get thirsty, neither come all the way here to draw."'),
  ('eba7da97-cdee-5269-aa6b-1ac14d008fe3', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 16, 16, 'Jesus said to her, "Go, call your husband, and come here."'),
  ('ed5f1c83-79d8-5682-a159-3d235b466f3e', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 17, 17, 'The woman answered, "I have no husband." Jesus said to her, "You said well, ''I have no husband,'''),
  ('fe636944-2fcb-5458-a624-65adb27cbca3', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 18, 18, 'for you have had five husbands; and he whom you now have is not your husband. This you have said truly."'),
  ('d2e0e96f-daed-5cbd-a760-7e52a1e736cd', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 19, 19, 'The woman said to him, "Sir, I perceive that you are a prophet.'),
  ('e34145e0-b7ae-5cc1-a4a1-77af9157d0c2', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 20, 20, 'Our fathers worshiped in this mountain, and you Jews say that in Jerusalem is the place where people ought to worship."'),
  ('8d647b5b-808d-5a88-a40e-d083891701e4', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 21, 21, 'Jesus said to her, "Woman, believe me, the hour comes, when neither in this mountain, nor in Jerusalem, will you worship the Father.'),
  ('9c40c7c7-f0c2-5d5a-a00a-2ea322b73c06', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 22, 22, 'You worship that which you don''t know. We worship that which we know; for salvation is from the Jews.'),
  ('8cf98258-a808-5256-ac3a-54a13fbd81b5', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 23, 23, 'But the hour comes, and now is, when the true worshippers will worship the Father in spirit and truth, for the Father seeks such to be his worshippers.'),
  ('a5c93dc9-f8cc-5521-a816-52beae5c3817', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 24, 24, 'God is spirit, and those who worship him must worship in spirit and truth."'),
  ('12df2d5a-36f1-55b8-a615-5801f38c6280', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 25, 25, 'The woman said to him, "I know that Messiah comes," (he who is called Christ). "When he has come, he will declare to us all things."'),
  ('f2a84b18-e8c6-5529-a810-d3f32af14960', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 26, 26, 'Jesus said to her, "I am he, the one who speaks to you."'),
  ('4cec0ba4-819f-5d5f-acb7-aec8ff4fac06', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 27, 27, 'At this, his disciples came. They marveled that he was speaking with a woman; yet no one said, "What are you looking for?" or, "Why do you speak with her?"'),
  ('707ff37c-a89a-5efb-ae48-d88eb9a6ba5f', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 28, 28, 'So the woman left her water pot, and went away into the city, and said to the people,'),
  ('d22db622-0347-518f-af63-764870da0de9', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 29, 29, '"Come, see a man who told me everything that I did. Can this be the Christ?"'),
  ('f0b72f47-d3b2-50fe-a214-02b0d6ce0b2b', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 30, 30, 'They went out of the city, and were coming to him.'),
  ('01fc5dfd-d15e-5c9c-ad00-878d57e5f94c', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 31, 31, 'In the meanwhile, the disciples urged him, saying, "Rabbi, eat."'),
  ('ae87fbe0-e3ba-5d38-ad08-c593995084cc', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 32, 32, 'But he said to them, "I have food to eat that you don''t know about."'),
  ('6d526e64-7c90-5d33-a50e-b19c75bbebda', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 33, 33, 'The disciples therefore said one to another, "Has anyone brought him something to eat?"'),
  ('524d7f43-4824-581e-a3ae-dc3cfc0e4c5d', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 34, 34, 'Jesus said to them, "My food is to do the will of him who sent me, and to accomplish his work.'),
  ('fb9a15e2-b4ff-544b-a8b7-74dd096e434d', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 35, 35, 'Don''t you say, ''There are yet four months until the harvest?'' Behold, I tell you, lift up your eyes, and look at the fields, that they are white for harvest already.'),
  ('c2003279-c586-5e01-ab72-fd87a01059da', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 36, 36, 'He who reaps receives wages, and gathers fruit to eternal life; that both he who sows and he who reaps may rejoice together.'),
  ('3b075362-e3d8-5479-a545-421f01d29a50', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 37, 37, 'For in this the saying is true, ''One sows, and another reaps.'''),
  ('bb33c985-da49-5e76-a835-1aae8cba02d6', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 38, 38, 'I sent you to reap that for which you haven''t labored. Others have labored, and you have entered into their labor."'),
  ('40b153e4-7e23-5434-a79b-07831e44050e', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 39, 39, 'From that city many of the Samaritans believed in him because of the word of the woman, who testified, "He told me everything that I did."'),
  ('ec33df57-22db-55ab-a22c-b6d3b56bf006', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 40, 40, 'So when the Samaritans came to him, they begged him to stay with them. He stayed there two days.'),
  ('3d953cdd-d20b-534c-ae2d-3008720a35dc', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 41, 41, 'Many more believed because of his word.'),
  ('b2b65a15-0b25-5eac-a77e-16870fed4b1f', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 42, 42, 'They said to the woman, "Now we believe, not because of your speaking; for we have heard for ourselves, and know that this is indeed the Christ, the Savior of the world."'),
  ('83fe70bb-aad9-553e-ae17-dd1c0aaf7043', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 43, 43, 'After the two days he went out from there and went into Galilee.'),
  ('8c1923d3-4282-5340-aec3-ef04cd68ab38', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 44, 44, 'For Jesus himself testified that a prophet has no honor in his own country.'),
  ('8c01166e-9e79-5ca7-a4f2-ae0977b3d0ce', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 45, 45, 'So when he came into Galilee, the Galileans received him, having seen all the things that he did in Jerusalem at the feast, for they also went to the feast.'),
  ('517bf3f3-e0a9-594d-a8b7-92c4ded75ceb', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 46, 46, 'Jesus came therefore again to Cana of Galilee, where he made the water into wine. There was a certain nobleman whose son was sick at Capernaum.'),
  ('7810246f-d1fa-562c-a94c-4cee3d709b3f', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 47, 47, 'When he heard that Jesus had come out of Judea into Galilee, he went to him, and begged him that he would come down and heal his son, for he was at the point of death.'),
  ('2822bb30-270f-5533-ad25-d4d799ec39f9', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 48, 48, 'Jesus therefore said to him, "Unless you see signs and wonders, you will in no way believe."'),
  ('d933a1fd-59ff-5bec-a68b-ac77f0e8c44d', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 49, 49, 'The nobleman said to him, "Sir, come down before my child dies."'),
  ('4bd661ba-fbbd-5200-a1b9-0a61a36cac36', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 50, 50, 'Jesus said to him, "Go your way. Your son lives." The man believed the word that Jesus spoke to him, and he went his way.'),
  ('e367283a-81b6-5426-aad3-717b0710d456', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 51, 51, 'As he was now going down, his servants met him and reported, saying "Your child lives!"'),
  ('aa057da5-7540-5da3-ae12-1b354fc999de', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 52, 52, 'So he inquired of them the hour when he began to get better. They said therefore to him, "Yesterday at the seventh hour, the fever left him."'),
  ('8bc67ed7-9893-5b5c-a6bc-f38ed465cc9e', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 53, 53, 'So the father knew that it was at that hour in which Jesus said to him, "Your son lives." He believed, as did his whole house.'),
  ('8833c110-caa8-54fe-a2ff-bf269bfcfb13', 'b4be865d-b61e-596d-aff9-3eb28e23cb3d', NULL, 54, 54, 'This is again the second sign that Jesus did, having come out of Judea into Galilee.'),
  ('1910805b-ca1f-5803-a31f-94f01db2a1cd', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 1, 1, 'After these things, there was a feast of the Jews, and Jesus went up to Jerusalem.'),
  ('e338de57-7bc8-597b-a152-ba798e888689', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 2, 2, 'Now in Jerusalem by the sheep gate, there is a pool, which is called in Hebrew, "Bethesda," having five porches.'),
  ('718f391c-ecbc-5a5b-a29a-0111fb36fbce', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 3, 3, 'In these lay a great multitude of those who were sick, blind, lame, or paralyzed, waiting for the moving of the water;'),
  ('9d3841be-69b0-599b-abb5-6b19ee087fa1', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 4, 4, 'for an angel went down at certain times into the pool, and stirred up the water. Whoever stepped in first after the stirring of the water was made whole of whatever disease he had.'),
  ('ffcb6f03-5600-56ae-a3f7-28784409a17a', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 5, 5, 'A certain man was there, who had been sick for thirty-eight years.'),
  ('3bc93107-29ef-5e2e-a530-8e7fb4341368', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 6, 6, 'When Jesus saw him lying there, and knew that he had been sick for a long time, he asked him, "Do you want to be made well?"'),
  ('fb0e0ca4-79cd-5ccc-a6b3-895e0e8ae660', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 7, 7, 'The sick man answered him, "Sir, I have no one to put me into the pool when the water is stirred up, but while I''m coming, another steps down before me."'),
  ('e1d393b7-0760-5498-ae7d-b590c7e0e431', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 8, 8, 'Jesus said to him, "Arise, take up your mat, and walk."'),
  ('b08efb57-0de6-5b07-aa5b-6e66b5213264', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 9, 9, 'Immediately, the man was made well, and took up his mat and walked. Now it was the Sabbath on that day.'),
  ('c2885731-3509-5577-a0ce-204e0354e949', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 10, 10, 'So the Jews said to him who was cured, "It is the Sabbath. It is not lawful for you to carry the mat."'),
  ('a2e78f97-7887-5477-a939-be0f172373ff', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 11, 11, 'He answered them, "He who made me well, the same said to me, ''Take up your mat, and walk.''"'),
  ('38e57e25-8b9f-5870-a293-c6789049935b', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 12, 12, 'Then they asked him, "Who is the man who said to you, ''Take up your mat, and walk''?"'),
  ('8fd924a1-dc48-5e16-adbf-9e6c2d022b67', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 13, 13, 'But he who was healed didn''t know who it was, for Jesus had withdrawn, a crowd being in the place.'),
  ('d78e0175-0991-5607-a5cc-8a6c8c85887b', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 14, 14, 'Afterward Jesus found him in the temple, and said to him, "Behold, you are made well. Sin no more, so that nothing worse happens to you."'),
  ('0817cf46-7d0d-58b3-aca2-05272077c0a2', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 15, 15, 'The man went away, and told the Jews that it was Jesus who had made him well.'),
  ('81cd6c96-f4d4-58dc-a0a8-97208302f0f6', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 16, 16, 'For this cause the Jews persecuted Jesus, and sought to kill him, because he did these things on the Sabbath.'),
  ('b8c0c540-81b6-5390-add6-c61823a19da3', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 17, 17, 'But Jesus answered them, "My Father is still working, so I am working, too."'),
  ('3aea157c-4f90-50f1-ab07-66b3f916288e', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 18, 18, 'For this cause therefore the Jews sought all the more to kill him, because he not only broke the Sabbath, but also called God his own Father, making himself equal with God.'),
  ('19a58695-e5ad-5fa6-ac0b-9ca17d3fd00f', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 19, 19, 'Jesus therefore answered them, "Most certainly, I tell you, the Son can do nothing of himself, but what he sees the Father doing. For whatever things he does, these the Son also does likewise.'),
  ('3b7d96bb-e08f-5422-a7a3-e700e2a4005e', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 20, 20, 'For the Father has affection for the Son, and shows him all things that he himself does. He will show him greater works than these, that you may marvel.'),
  ('def06a6f-8718-539d-a519-3563c13b4938', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 21, 21, 'For as the Father raises the dead and gives them life, even so the Son also gives life to whom he desires.'),
  ('f2a28c2a-3bf8-57d6-ae07-c292bcd90f33', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 22, 22, 'For the Father judges no one, but he has given all judgment to the Son,'),
  ('a7583a6b-b5d7-5d39-aca6-c53429d60d53', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 23, 23, 'that all may honor the Son, even as they honor the Father. He who doesn''t honor the Son doesn''t honor the Father who sent him.'),
  ('e0b15671-f6bc-5768-a4af-1bd5857d5a85', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 24, 24, '"Most certainly I tell you, he who hears my word, and believes him who sent me, has eternal life, and doesn''t come into judgment, but has passed out of death into life.'),
  ('f8106b48-3086-5089-a3fa-fb608d058675', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 25, 25, 'Most certainly, I tell you, the hour comes, and now is, when the dead will hear the Son of God''s voice; and those who hear will live.'),
  ('716e176b-72fd-5d33-a27c-1e70ecb9d95e', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 26, 26, 'For as the Father has life in himself, even so he gave to the Son also to have life in himself.'),
  ('74c8922f-95d5-5e5b-aa04-c979c575018d', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 27, 27, 'He also gave him authority to execute judgment, because he is a son of man.'),
  ('09132c69-c310-5cbf-a414-408f9894d08a', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 28, 28, 'Don''t marvel at this, for the hour comes, in which all that are in the tombs will hear his voice,'),
  ('20ac24c7-989a-522e-a153-13977a35a84c', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 29, 29, 'and will come out; those who have done good, to the resurrection of life; and those who have done evil, to the resurrection of judgment.'),
  ('3c13bc6e-6f28-57fa-a995-107e8cf1eaa8', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 30, 30, 'I can of myself do nothing. As I hear, I judge, and my judgment is righteous; because I don''t seek my own will, but the will of my Father who sent me.'),
  ('9ea88e29-e5cb-570e-a142-42f66cb63b74', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 31, 31, '"If I testify about myself, my witness is not valid.'),
  ('09931b76-2864-5926-a0ec-4d7c74978cd9', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 32, 32, 'It is another who testifies about me. I know that the testimony which he testifies about me is true.'),
  ('9b4faae7-aff5-53f7-acb7-5081a9dd9104', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 33, 33, 'You have sent to John, and he has testified to the truth.'),
  ('32f6c067-109b-5352-ac47-17ae94e9a399', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 34, 34, 'But the testimony which I receive is not from man. However, I say these things that you may be saved.'),
  ('83bc0fb0-a582-5b58-aa72-3b11910724db', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 35, 35, 'He was the burning and shining lamp, and you were willing to rejoice for a while in his light.'),
  ('9e55f940-b35a-554a-a272-9ff6755050ed', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 36, 36, 'But the testimony which I have is greater than that of John, for the works which the Father gave me to accomplish, the very works that I do, testify about me, that the Father has sent me.'),
  ('2f92cf74-f9ea-597b-a69b-39bd700670b3', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 37, 37, 'The Father himself, who sent me, has testified about me. You have neither heard his voice at any time, nor seen his form.'),
  ('7af758cb-be7c-5292-ad07-07e68784882b', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 38, 38, 'You don''t have his word living in you; because you don''t believe him whom he sent.'),
  ('2b6353ef-c749-5be2-ae24-58386174a535', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 39, 39, '"You search the Scriptures, because you think that in them you have eternal life; and these are they which testify about me.'),
  ('3cb767e0-6a5b-5d7a-abae-75f5c2f56c45', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 40, 40, 'Yet you will not come to me, that you may have life.'),
  ('0b10c8e1-0b81-5257-a494-4f4721820fb9', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 41, 41, 'I don''t receive glory from men.'),
  ('38ac741b-5e7a-5af6-a84b-999c3f939d4f', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 42, 42, 'But I know you, that you don''t have God''s love in yourselves.'),
  ('7d2daf91-a817-51b8-ae74-9575895eff6c', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 43, 43, 'I have come in my Father''s name, and you don''t receive me. If another comes in his own name, you will receive him.'),
  ('c4dccc0b-3e36-5270-a1d5-d5ef77f95185', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 44, 44, 'How can you believe, who receive glory from one another, and you don''t seek the glory that comes from the only God?'),
  ('8f1cd745-4fb8-56e8-a5ee-11b11b4fe897', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 45, 45, '"Don''t think that I will accuse you to the Father. There is one who accuses you, even Moses, on whom you have set your hope.'),
  ('2046ca18-69d8-5c8d-a45f-d0bfb3415bf2', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 46, 46, 'For if you believed Moses, you would believe me; for he wrote about me.'),
  ('51036b6c-5d3d-51a4-ae20-c213256720c0', '3c9eba58-ec56-5e3a-a217-20014c91940a', NULL, 47, 47, 'But if you don''t believe his writings, how will you believe my words?"'),
  ('207a0188-2172-57a1-afa4-33af34695b80', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 1, 1, 'After these things, Jesus went away to the other side of the sea of Galilee, which is also called the Sea of Tiberias.'),
  ('1ccc7436-740f-563e-af58-123baf884c78', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 2, 2, 'A great multitude followed him, because they saw his signs which he did on those who were sick.'),
  ('ff196b2f-7145-5268-af36-c0ee8652bb32', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 3, 3, 'Jesus went up into the mountain, and he sat there with his disciples.'),
  ('c2637964-c7d6-5324-a98a-ea40875f93ad', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 4, 4, 'Now the Passover, the feast of the Jews, was at hand.'),
  ('c7a1e259-af19-5ffb-ab1c-1b874d97ba10', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 5, 5, 'Jesus therefore lifting up his eyes, and seeing that a great multitude was coming to him, said to Philip, "Where are we to buy bread, that these may eat?"'),
  ('d5f08d10-e82a-50ff-a9b4-d238fc3d41de', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 6, 6, 'This he said to test him, for he himself knew what he would do.'),
  ('3372edf4-9d86-56e9-a686-724e46b86be4', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 7, 7, 'Philip answered him, "Two hundred denarii worth of bread is not sufficient for them, that everyone of them may receive a little."'),
  ('83c9d3da-e406-5267-aa3d-57daa34fb9a9', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 8, 8, 'One of his disciples, Andrew, Simon Peter''s brother, said to him,'),
  ('cb88091e-d070-554b-a845-7d2b49a9f64f', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 9, 9, '"There is a boy here who has five barley loaves and two fish, but what are these among so many?"'),
  ('08ab8367-4299-5481-a444-cdfb42c192f8', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 10, 10, 'Jesus said, "Have the people sit down." Now there was much grass in that place. So the men sat down, in number about five thousand.'),
  ('99d214bb-daf1-57fb-af29-701f0e706e20', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 11, 11, 'Jesus took the loaves; and having given thanks, he distributed to the disciples, and the disciples to those who were sitting down; likewise also of the fish as much as they desired.'),
  ('a19eccda-ea41-5255-a4d4-f4ac7092e81f', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 12, 12, 'When they were filled, he said to his disciples, "Gather up the broken pieces which are left over, that nothing be lost."'),
  ('6d243236-15e8-5119-a175-ef2949dd2640', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 13, 13, 'So they gathered them up, and filled twelve baskets with broken pieces from the five barley loaves, which were left over by those who had eaten.'),
  ('bce071da-5118-52b2-a5bc-32437ac8a6dd', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 14, 14, 'When therefore the people saw the sign which Jesus did, they said, "This is truly the prophet who comes into the world."'),
  ('b7828466-e3ad-5df2-a10b-35e7e78dc14e', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 15, 15, 'Jesus therefore, perceiving that they were about to come and take him by force, to make him king, withdrew again to the mountain by himself.'),
  ('cfde12ac-e000-5d4b-a6f8-1d56348b7282', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 16, 16, 'When evening came, his disciples went down to the sea,'),
  ('477bffc1-3085-5169-acde-c2aef2faa685', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 17, 17, 'and they entered into the boat, and were going over the sea to Capernaum. It was now dark, and Jesus had not come to them.'),
  ('7aac2773-ed08-5148-a8c3-a7908b530521', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 18, 18, 'The sea was tossed by a great wind blowing.'),
  ('455e96fc-164a-5a63-ac84-14a6fadd44f3', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 19, 19, 'When therefore they had rowed about twenty-five or thirty stadia, they saw Jesus walking on the sea, and drawing near to the boat; and they were afraid.'),
  ('47af1dc4-85cb-52cc-afcd-efab08e0aec9', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 20, 20, 'But he said to them, "It is I. Don''t be afraid."'),
  ('051df4b2-bfe5-51f5-aafe-bc42b964af2d', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 21, 21, 'They were willing therefore to receive him into the boat. Immediately the boat was at the land where they were going.'),
  ('a56aee8d-abdb-52a9-ad78-78a7b92ef28f', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 22, 22, 'On the next day, the multitude that stood on the other side of the sea saw that there was no other boat there, except the one in which his disciples had embarked, and that Jesus hadn''t entered with his disciples into the boat, but his disciples had gone away alone.'),
  ('ef811b79-35cb-5ddd-ac66-cb851e000bc8', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 23, 23, 'However boats from Tiberias came near to the place where they ate the bread after the Lord had given thanks.'),
  ('18617a2a-765f-5ce4-a53c-6fc92003706c', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 24, 24, 'When the multitude therefore saw that Jesus wasn''t there, nor his disciples, they themselves got into the boats, and came to Capernaum, seeking Jesus.'),
  ('4afa53be-9b44-56bd-a424-546bf8448e35', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 25, 25, 'When they found him on the other side of the sea, they asked him, "Rabbi, when did you come here?"'),
  ('3af7ac89-453e-5ec2-ad23-5fd6e989513c', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 26, 26, 'Jesus answered them, "Most certainly I tell you, you seek me, not because you saw signs, but because you ate of the loaves, and were filled.'),
  ('00af48ad-6d10-5cbf-aac1-0e6f75c2ca3f', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 27, 27, 'Don''t work for the food which perishes, but for the food which remains to eternal life, which the Son of Man will give to you. For God the Father has sealed him."'),
  ('db98593e-a540-5cf5-a06e-6bc59632cc09', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 28, 28, 'They said therefore to him, "What must we do, that we may work the works of God?"'),
  ('04419637-cad2-54a6-ae06-1f3405625cb4', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 29, 29, 'Jesus answered them, "This is the work of God, that you believe in him whom he has sent."'),
  ('104afe3d-f1f3-5435-a006-d9f4b914e055', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 30, 30, 'They said therefore to him, "What then do you do for a sign, that we may see, and believe you? What work do you do?'),
  ('8de7f139-398f-5388-aec6-fb7b3ad495ad', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 31, 31, 'Our fathers ate the manna in the wilderness. As it is written, ''He gave them bread out of heaven to eat.''"'),
  ('6e0143ce-2a05-54d2-a72e-34b764aed7ba', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 32, 32, 'Jesus therefore said to them, "Most certainly, I tell you, it wasn''t Moses who gave you the bread out of heaven, but my Father gives you the true bread out of heaven.'),
  ('57da6ef6-bb83-5904-a3e0-2d04e52f3f99', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 33, 33, 'For the bread of God is that which comes down out of heaven, and gives life to the world."'),
  ('468a2841-1827-5d6e-ad00-f35c418bf3c5', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 34, 34, 'They said therefore to him, "Lord, always give us this bread."'),
  ('14c8bf4e-046c-5495-aad7-16cbab229a18', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 35, 35, 'Jesus said to them, "I am the bread of life. He who comes to me will not be hungry, and he who believes in me will never be thirsty.'),
  ('5ae9df21-85f2-5d11-ab36-b75d378ca768', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 36, 36, 'But I told you that you have seen me, and yet you don''t believe.'),
  ('4ebc9de5-c2ab-53f3-af64-9c646d796c76', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 37, 37, 'All those who the Father gives me will come to me. Him who comes to me I will in no way throw out.'),
  ('758a85f6-22c3-57ce-a39f-1c81824a7906', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 38, 38, 'For I have come down from heaven, not to do my own will, but the will of him who sent me.'),
  ('62c1583a-e8bb-5906-afc0-7e1ed8a5a404', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 39, 39, 'This is the will of my Father who sent me, that of all he has given to me I should lose nothing, but should raise him up at the last day.'),
  ('77e9c37b-fd31-5d2c-a5d2-b06cac88b6ad', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 40, 40, 'This is the will of the one who sent me, that everyone who sees the Son, and believes in him, should have eternal life; and I will raise him up at the last day."'),
  ('94beb53b-48c9-50f0-a2c7-5e3d87bbc284', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 41, 41, 'The Jews therefore murmured concerning him, because he said, "I am the bread which came down out of heaven."'),
  ('dca33f3a-8e58-56a3-ade1-312278879baa', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 42, 42, 'They said, "Isn''t this Jesus, the son of Joseph, whose father and mother we know? How then does he say, ''I have come down out of heaven?''"'),
  ('984ce676-ef11-5f52-a4a9-bf1ab09435ec', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 43, 43, 'Therefore Jesus answered them, "Don''t murmur among yourselves.'),
  ('03e483c6-fb43-586b-a777-5620ac231aed', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 44, 44, 'No one can come to me unless the Father who sent me draws him, and I will raise him up in the last day.'),
  ('4d0623b0-3981-5f7e-a09f-99b19a294618', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 45, 45, 'It is written in the prophets, ''They will all be taught by God.'' Therefore everyone who hears from the Father, and has learned, comes to me.'),
  ('a367a943-4f7b-58d0-af2f-48f42b190eae', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 46, 46, 'Not that anyone has seen the Father, except he who is from God. He has seen the Father.'),
  ('032da0d6-cebb-5ec7-a681-3e7a5b39eb8c', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 47, 47, 'Most certainly, I tell you, he who believes in me has eternal life.'),
  ('5446a5f3-4bc9-5be4-a634-8551596b43e1', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 48, 48, 'I am the bread of life.'),
  ('fe4670c0-c82a-5125-aeac-a7ff87a4e945', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 49, 49, 'Your fathers ate the manna in the wilderness, and they died.'),
  ('c1ac39f8-1577-51d0-ac62-d893e55c5d2f', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 50, 50, 'This is the bread which comes down out of heaven, that anyone may eat of it and not die.'),
  ('fee599db-d077-55bf-ac19-3941f305593b', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 51, 51, 'I am the living bread which came down out of heaven. If anyone eats of this bread, he will live forever. Yes, the bread which I will give for the life of the world is my flesh."'),
  ('e9276eef-dbf9-58fd-a8f1-5034ab0f9aed', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 52, 52, 'The Jews therefore contended with one another, saying, "How can this man give us his flesh to eat?"'),
  ('a99db30d-033e-5932-a633-3cd92555177c', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 53, 53, 'Jesus therefore said to them, "Most certainly I tell you, unless you eat the flesh of the Son of Man and drink his blood, you don''t have life in yourselves.'),
  ('8a8ef5ac-0020-5313-a231-7373764d8bac', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 54, 54, 'He who eats my flesh and drinks my blood has eternal life, and I will raise him up at the last day.'),
  ('c6664c29-a4b4-5d30-a664-ff3729835e2b', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 55, 55, 'For my flesh is food indeed, and my blood is drink indeed.'),
  ('31d0c80c-b82c-524b-a791-a548b77afab0', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 56, 56, 'He who eats my flesh and drinks my blood lives in me, and I in him.'),
  ('facc26d6-da5c-526b-aab9-fec6825cf938', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 57, 57, 'As the living Father sent me, and I live because of the Father; so he who feeds on me, he will also live because of me.'),
  ('dfa940ce-33cc-5b52-ac7c-fd372af5dc59', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 58, 58, 'This is the bread which came down out of heaven--not as our fathers ate the manna, and died. He who eats this bread will live forever."'),
  ('3efd8da9-4fe1-500c-add4-6514528f185a', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 59, 59, 'He said these things in the synagogue, as he taught in Capernaum.'),
  ('d6a68000-7884-5076-a4bd-77c1fc88a5f7', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 60, 60, 'Therefore many of his disciples, when they heard this, said, "This is a hard saying! Who can listen to it?"'),
  ('a28902fb-5c76-5612-a84c-e3faf0e074d9', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 61, 61, 'But Jesus knowing in himself that his disciples murmured at this, said to them, "Does this cause you to stumble?'),
  ('5393b857-2beb-54c8-a467-81c5098f0f33', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 62, 62, 'Then what if you would see the Son of Man ascending to where he was before?'),
  ('e5a5b7f5-35de-558f-a3ce-07ad8329ca71', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 63, 63, 'It is the spirit who gives life. The flesh profits nothing. The words that I speak to you are spirit, and are life.'),
  ('0a9981ba-5315-55f5-a05f-9e81c773e617', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 64, 64, 'But there are some of you who don''t believe." For Jesus knew from the beginning who they were who didn''t believe, and who it was who would betray him.'),
  ('a5c10350-15c3-5c5c-ac74-40a27c827ecc', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 65, 65, 'He said, "For this cause have I said to you that no one can come to me, unless it is given to him by my Father."'),
  ('3c2c7e56-9755-5da1-a136-6bf833d93328', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 66, 66, 'At this, many of his disciples went back, and walked no more with him.'),
  ('57612871-3c37-5528-a551-7a2554dfd631', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 67, 67, 'Jesus said therefore to the twelve, "You don''t also want to go away, do you?"'),
  ('47a1d834-16a8-5357-abf4-5833a64667bc', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 68, 68, 'Simon Peter answered him, "Lord, to whom would we go? You have the words of eternal life.'),
  ('bd67bba5-3437-5596-ac0b-e2a7cc933ca5', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 69, 69, 'We have come to believe and know that you are the Christ, the Son of the living God."'),
  ('f96d96a4-104a-5ed3-a860-8a7d01dcfe5f', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 70, 70, 'Jesus answered them, "Didn''t I choose you, the twelve, and one of you is a devil?"'),
  ('69f3df95-ccd3-5329-a679-b6f4afc494ca', '1cf1d30c-9a5e-56e8-a940-9ef0ecf40c4f', NULL, 71, 71, 'Now he spoke of Judas, the son of Simon Iscariot, for it was he who would betray him, being one of the twelve.'),
  ('21b7e50a-635e-5d3a-adb4-1342ab1122ea', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 1, 1, 'After these things, Jesus was walking in Galilee, for he wouldn''t walk in Judea, because the Jews sought to kill him.'),
  ('f8481218-f819-5079-ac8f-6cdcb722a3a7', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 2, 2, 'Now the feast of the Jews, the Feast of Booths, was at hand.'),
  ('e0b2fe67-2f14-5e94-a129-44139c32144b', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 3, 3, 'His brothers therefore said to him, "Depart from here, and go into Judea, that your disciples also may see your works which you do.'),
  ('d0ea36e4-ebe0-54b2-a07e-5a6064afb8e7', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 4, 4, 'For no one does anything in secret, and himself seeks to be known openly. If you do these things, reveal yourself to the world."'),
  ('477a4d73-99d0-5d2e-a34f-984eef40e108', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 5, 5, 'For even his brothers didn''t believe in him.'),
  ('f22d27df-afee-577b-a04d-c2bfcd9e3f5e', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 6, 6, 'Jesus therefore said to them, "My time has not yet come, but your time is always ready.'),
  ('d5bee58d-fbaa-51db-a332-7f9e461c4ef0', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 7, 7, 'The world can''t hate you, but it hates me, because I testify about it, that its works are evil.'),
  ('fcea63db-e54a-5482-a9c2-cf1e7836154c', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 8, 8, 'You go up to the feast. I am not yet going up to this feast, because my time is not yet fulfilled."'),
  ('fd4ebb16-9c7a-5a78-a664-5d7318ee58ee', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 9, 9, 'Having said these things to them, he stayed in Galilee.'),
  ('eed42f14-b421-59aa-a3d3-55622be969e9', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 10, 10, 'But when his brothers had gone up to the feast, then he also went up, not publicly, but as it were in secret.'),
  ('4709acf4-833d-576e-a63c-5ef56df3b389', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 11, 11, 'The Jews therefore sought him at the feast, and said, "Where is he?"'),
  ('1c8eabaa-857d-5265-adb1-85ad9a106586', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 12, 12, 'There was much murmuring among the multitudes concerning him. Some said, "He is a good man." Others said, "Not so, but he leads the multitude astray."'),
  ('51928640-fd62-5082-a611-e10b471b67ba', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 13, 13, 'Yet no one spoke openly of him for fear of the Jews.'),
  ('aacce809-03d7-59e5-a21c-427944735d4a', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 14, 14, 'But when it was now the midst of the feast, Jesus went up into the temple and taught.'),
  ('adb3af6f-2e14-5cd9-a2f5-732c6428628a', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 15, 15, 'The Jews therefore marveled, saying, "How does this man know letters, having never been educated?"'),
  ('6a065ceb-d765-58a4-a66e-0ee318e23df5', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 16, 16, 'Jesus therefore answered them, "My teaching is not mine, but his who sent me.'),
  ('b586bff6-caa9-5d56-a1c6-e5d89ea69fab', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 17, 17, 'If anyone desires to do his will, he will know about the teaching, whether it is from God, or if I am speaking from myself.'),
  ('e5350305-dc11-5cf9-aff6-0a683a09ebf9', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 18, 18, 'He who speaks from himself seeks his own glory, but he who seeks the glory of him who sent him is true, and no unrighteousness is in him.'),
  ('a5fb29b7-60b2-5463-a387-e4a355f3f13b', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 19, 19, 'Didn''t Moses give you the law, and yet none of you keeps the law? Why do you seek to kill me?"'),
  ('1154cef6-9619-5e6a-aade-c921cfdb637d', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 20, 20, 'The multitude answered, "You have a demon! Who seeks to kill you?"'),
  ('3b2632d7-5aca-5706-ad5f-7152e498af2b', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 21, 21, 'Jesus answered them, "I did one work, and you all marvel because of it.'),
  ('a294149c-40a9-530d-af14-8a1399e94ecb', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 22, 22, 'Moses has given you circumcision (not that it is of Moses, but of the fathers), and on the Sabbath you circumcise a boy.'),
  ('f15adc94-41ce-5ed5-a024-bd3580231f3d', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 23, 23, 'If a boy receives circumcision on the Sabbath, that the law of Moses may not be broken, are you angry with me, because I made a man completely healthy on the Sabbath?'),
  ('3ce49191-2dd7-5d2c-afb6-12cc526972a5', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 24, 24, 'Don''t judge according to appearance, but judge righteous judgment."'),
  ('938b811a-fe38-5c7a-a033-1481f806930a', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 25, 25, 'Therefore some of them of Jerusalem said, "Isn''t this he whom they seek to kill?'),
  ('11790e93-11ff-5a25-abf3-35f05eb22109', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 26, 26, 'Behold, he speaks openly, and they say nothing to him. Can it be that the rulers indeed know that this is truly the Christ?'),
  ('efd51af9-ed9e-5163-a392-6effb187fe78', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 27, 27, 'However we know where this man comes from, but when the Christ comes, no one will know where he comes from."'),
  ('12f31194-caa6-5bac-a196-5edaadc74bac', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 28, 28, 'Jesus therefore cried out in the temple, teaching and saying, "You both know me, and know where I am from. I have not come of myself, but he who sent me is true, whom you don''t know.'),
  ('2c9b99e0-ddbb-5bd0-a760-e014d5fe45a8', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 29, 29, 'I know him, because I am from him, and he sent me."'),
  ('ae69c0fd-2d7d-5e84-a555-d9de2e90ccd0', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 30, 30, 'They sought therefore to take him; but no one laid a hand on him, because his hour had not yet come.'),
  ('4f66054a-af17-5112-a857-783bf7cf480e', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 31, 31, 'But of the multitude, many believed in him. They said, "When the Christ comes, he won''t do more signs than those which this man has done, will he?"'),
  ('e55d15b4-c987-55c3-ad4c-a6595b62116d', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 32, 32, 'The Pharisees heard the multitude murmuring these things concerning him, and the chief priests and the Pharisees sent officers to arrest him.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('104d2bf9-b68c-5b76-a9f9-3d0d9860ec80', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 33, 33, 'Then Jesus said, "I will be with you a little while longer, then I go to him who sent me.'),
  ('e65117ba-6653-5e29-a279-83217a8eec37', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 34, 34, 'You will seek me, and won''t find me; and where I am, you can''t come."'),
  ('a6f4454b-f095-5b9b-a7e2-005648c850b1', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 35, 35, 'The Jews therefore said among themselves, "Where will this man go that we won''t find him? Will he go to the Dispersion among the Greeks, and teach the Greeks?'),
  ('b658e265-a0b1-5c5f-ae0f-e4f532c4216e', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 36, 36, 'What is this word that he said, ''You will seek me, and won''t find me; and where I am, you can''t come''?"'),
  ('2c05009e-8af3-5f89-a102-7dfd2dce67cf', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 37, 37, 'Now on the last and greatest day of the feast, Jesus stood and cried out, "If anyone is thirsty, let him come to me and drink!'),
  ('f27f06b3-50ad-5e1d-a69c-5002d6edb2a0', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 38, 38, 'He who believes in me, as the Scripture has said, from within him will flow rivers of living water."'),
  ('9fe173e6-2c6a-503e-ad57-45ede3fcb661', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 39, 39, 'But he said this about the Spirit, which those believing in him were to receive. For the Holy Spirit was not yet given, because Jesus wasn''t yet glorified.'),
  ('ed0ac309-6109-559d-a47e-163fcb40dd0f', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 40, 40, 'Many of the multitude therefore, when they heard these words, said, "This is truly the prophet."'),
  ('a9c783e2-4475-5d33-aca6-ede506f6de0e', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 41, 41, 'Others said, "This is the Christ." But some said, "What, does the Christ come out of Galilee?'),
  ('42c962d2-1eea-5882-a24c-15069a82e5e3', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 42, 42, 'Hasn''t the Scripture said that the Christ comes of the seed of David, and from Bethlehem, the village where David was?"'),
  ('5aafa942-93d8-5dae-a24c-128f10188686', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 43, 43, 'So there arose a division in the multitude because of him.'),
  ('dccad350-1ecf-5c0f-a9c9-6635b893493f', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 44, 44, 'Some of them would have arrested him, but no one laid hands on him.'),
  ('a362ab03-2639-55d3-a47e-f80afff28de8', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 45, 45, 'The officers therefore came to the chief priests and Pharisees, and they said to them, "Why didn''t you bring him?"'),
  ('60a2e559-8b59-58e6-acb5-e8307a74c85c', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 46, 46, 'The officers answered, "No man ever spoke like this man!"'),
  ('21e54052-ffbe-5462-a506-334d1f065e9e', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 47, 47, 'The Pharisees therefore answered them, "You aren''t also led astray, are you?'),
  ('ea9ac7dd-7c2d-57f9-a168-aca73205284e', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 48, 48, 'Have any of the rulers believed in him, or of the Pharisees?'),
  ('2d543d8d-b6af-52e2-a51f-b92a0c5171db', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 49, 49, 'But this multitude that doesn''t know the law is accursed."'),
  ('e0148e0b-e09e-55a4-a24b-19726d744482', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 50, 50, 'Nicodemus (he who came to him by night, being one of them) said to them,'),
  ('c9ce73f8-f890-5041-a20d-8235f8c5455f', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 51, 51, '"Does our law judge a man, unless it first hears from him personally and knows what he does?"'),
  ('73f6f139-544c-59fe-a355-6b1602658d24', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 52, 52, 'They answered him, "Are you also from Galilee? Search, and see that no prophet has arisen out of Galilee."'),
  ('3eaac227-9389-5946-a2c6-d896cc27384f', '15e8f6ff-a56e-5182-a4f3-65d8e2e9e186', NULL, 53, 53, 'Everyone went to his own house,'),
  ('4e7f6220-9149-54e8-ab1b-84eef2267246', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 1, 1, 'but Jesus went to the Mount of Olives.'),
  ('484d8a8e-998c-59ae-acba-349d4f76ae02', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 2, 2, 'Now very early in the morning, he came again into the temple, and all the people came to him. He sat down, and taught them.'),
  ('a67c63ef-c9be-5d9b-a34f-5bb7f9c48aba', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 3, 3, 'The scribes and the Pharisees brought a woman taken in adultery. Having set her in the midst,'),
  ('ae0313d3-534e-5d00-afb2-46a496de9ea6', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 4, 4, 'they told him, "Teacher, we found this woman in adultery, in the very act.'),
  ('d2cee616-a861-50cd-ab66-11c52de3a279', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 5, 5, 'Now in our law, Moses commanded us to stone such. What then do you say about her?"'),
  ('5150a5c0-c6cb-5088-a93c-401272dbb08e', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 6, 6, 'They said this testing him, that they might have something to accuse him of. But Jesus stooped down, and wrote on the ground with his finger.'),
  ('0bf0f79d-ce0a-5a14-a603-178109939d75', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 7, 7, 'But when they continued asking him, he looked up and said to them, "He who is without sin among you, let him throw the first stone at her."'),
  ('57ae3aca-ac11-5632-adfe-d7c566cc6f59', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 8, 8, 'Again he stooped down, and with his finger wrote on the ground.'),
  ('cbe9e27d-5dc4-5cf1-a853-af3c03fb5f7f', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 9, 9, 'They, when they heard it, being convicted by their conscience, went out one by one, beginning from the oldest, even to the last. Jesus was left alone with the woman where she was, in the middle.'),
  ('a279b343-e4f7-5d70-a1af-61ce16a8f1e7', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 10, 10, 'Jesus, standing up, saw her and said, "Woman, where are your accusers? Did no one condemn you?"'),
  ('8105c55d-25ce-5f82-a00a-9fd0a32ec491', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 11, 11, 'She said, "No one, Lord." Jesus said, "Neither do I condemn you. Go your way. From now on, sin no more."'),
  ('c7340c3f-a049-5e6b-a080-8bb4731f8c33', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 12, 12, 'Again, therefore, Jesus spoke to them, saying, "I am the light of the world. He who follows me will not walk in the darkness, but will have the light of life."'),
  ('bc7dc101-1d99-5b10-ad9c-edbe2f5ec736', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 13, 13, 'The Pharisees therefore said to him, "You testify about yourself. Your testimony is not valid."'),
  ('80325efc-b58f-5eee-a938-5c8ec169e235', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 14, 14, 'Jesus answered them, "Even if I testify about myself, my testimony is true, for I know where I came from, and where I am going; but you don''t know where I came from, or where I am going.'),
  ('2c84c686-5622-5cc7-a63b-322d85e84bcb', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 15, 15, 'You judge according to the flesh. I judge no one.'),
  ('3053712e-594a-5f82-a8bf-0a9e335a25f7', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 16, 16, 'Even if I do judge, my judgment is true, for I am not alone, but I am with the Father who sent me.'),
  ('6fb0c165-6d9b-5554-af5c-7b09882ad187', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 17, 17, 'It''s also written in your law that the testimony of two people is valid.'),
  ('c54aa563-d64a-5812-a106-9eda6ded3405', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 18, 18, 'I am one who testifies about myself, and the Father who sent me testifies about me."'),
  ('11c37084-95a4-5c89-af8c-ac62a62b328e', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 19, 19, 'They said therefore to him, "Where is your Father?" Jesus answered, "You know neither me, nor my Father. If you knew me, you would know my Father also."'),
  ('019469f1-6d23-5cf8-a626-40fcc1e3b74f', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 20, 20, 'Jesus spoke these words in the treasury, as he taught in the temple. Yet no one arrested him, because his hour had not yet come.'),
  ('0a0201d7-8150-5b31-a8ce-ffa3284f7efc', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 21, 21, 'Jesus said therefore again to them, "I am going away, and you will seek me, and you will die in your sins. Where I go, you can''t come."'),
  ('b02b9393-e4ef-5ff6-a06c-0d1b79fd933f', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 22, 22, 'The Jews therefore said, "Will he kill himself, that he says, ''Where I am going, you can''t come?''"'),
  ('d36966cf-2cd6-5bd9-ad35-03f9dcb58680', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 23, 23, 'He said to them, "You are from beneath. I am from above. You are of this world. I am not of this world.'),
  ('23124726-dead-5200-aa73-4973c5a15869', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 24, 24, 'I said therefore to you that you will die in your sins; for unless you believe that I am he, you will die in your sins."'),
  ('76d37ee9-f3e5-5d6e-aff9-c126ee1b2f0c', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 25, 25, 'They said therefore to him, "Who are you?" Jesus said to them, "Just what I have been saying to you from the beginning.'),
  ('f0ae3ab5-af34-5ad3-a9f2-9afe410c3afd', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 26, 26, 'I have many things to speak and to judge concerning you. However he who sent me is true; and the things which I heard from him, these I say to the world."'),
  ('dcaf5e9c-0bc8-54bb-a014-a5b96a453fc6', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 27, 27, 'They didn''t understand that he spoke to them about the Father.'),
  ('2e50ce78-5bc1-55ba-afe0-66ac6fb48538', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 28, 28, 'Jesus therefore said to them, "When you have lifted up the Son of Man, then you will know that I am he, and I do nothing of myself, but as my Father taught me, I say these things.'),
  ('94d570b5-dc36-5825-aa87-3c4feedb5f3d', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 29, 29, 'He who sent me is with me. The Father hasn''t left me alone, for I always do the things that are pleasing to him."'),
  ('06c6be75-d080-50af-a957-24442c7a5041', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 30, 30, 'As he spoke these things, many believed in him.'),
  ('fec6874c-4602-5db9-a9bf-be906c8c9aa6', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 31, 31, 'Jesus therefore said to those Jews who had believed him, "If you remain in my word, then you are truly my disciples.'),
  ('1d1cd918-fac6-59b9-a224-1557934962d5', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 32, 32, 'You will know the truth, and the truth will make you free."'),
  ('946cb8a4-b43f-5c95-a4ab-289bca49bd3b', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 33, 33, 'They answered him, "We are Abraham''s seed, and have never been in bondage to anyone. How do you say, ''You will be made free?''"'),
  ('b0dcdaf8-2d08-51a7-a25c-e997f383e8b6', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 34, 34, 'Jesus answered them, "Most certainly I tell you, everyone who commits sin is the bondservant of sin.'),
  ('2136be33-122a-5c9e-ac98-21539b8a2976', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 35, 35, 'A bondservant doesn''t live in the house forever. A son remains forever.'),
  ('e346117c-2f69-5aa0-a036-7137e3f584a5', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 36, 36, 'If therefore the Son makes you free, you will be free indeed.'),
  ('a2a3f983-95a1-55f2-a86d-11c3866416fc', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 37, 37, 'I know that you are Abraham''s seed, yet you seek to kill me, because my word finds no place in you.'),
  ('2fa6c61c-3e80-5bdf-ae34-a640900b8fe1', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 38, 38, 'I say the things which I have seen with my Father; and you also do the things which you have seen with your father."'),
  ('5a638477-878a-5b11-a994-16e6287b1c86', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 39, 39, 'They answered him, "Our father is Abraham." Jesus said to them, "If you were Abraham''s children, you would do the works of Abraham.'),
  ('230303b4-033a-5a0c-a658-f725b6ca386d', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 40, 40, 'But now you seek to kill me, a man who has told you the truth, which I heard from God. Abraham didn''t do this.'),
  ('77d76275-a01c-52a3-aa8d-9251830252fd', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 41, 41, 'You do the works of your father." They said to him, "We were not born of sexual immorality. We have one Father, God."'),
  ('69e05184-b1fd-5600-a58d-3810c7b046c0', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 42, 42, 'Therefore Jesus said to them, "If God were your father, you would love me, for I came out and have come from God. For I haven''t come of myself, but he sent me.'),
  ('7b51f5fd-2b34-5909-aa29-68bdd7c5ae1e', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 43, 43, 'Why don''t you understand my speech? Because you can''t hear my word.'),
  ('77b98d42-2a99-5f86-a09d-979f4409c75b', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 44, 44, 'You are of your father, the devil, and you want to do the desires of your father. He was a murderer from the beginning, and doesn''t stand in the truth, because there is no truth in him. When he speaks a lie, he speaks on his own; for he is a liar, and its father.'),
  ('77df13e1-ed60-5cb9-af39-6471e4c6fc5e', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 45, 45, 'But because I tell the truth, you don''t believe me.'),
  ('5dbb656f-a86b-59ce-a251-c2487d730998', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 46, 46, 'Which of you convicts me of sin? If I tell the truth, why do you not believe me?'),
  ('a8d5a4e3-f629-591c-adbd-583f0dc40ee1', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 47, 47, 'He who is of God hears the words of God. For this cause you don''t hear, because you are not of God."'),
  ('cc0a065a-8899-5838-a90a-44e137c2a82b', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 48, 48, 'Then the Jews answered him, "Don''t we say well that you are a Samaritan, and have a demon?"'),
  ('88616010-2d19-57af-a4d6-03b1de2f9f9a', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 49, 49, 'Jesus answered, "I don''t have a demon, but I honor my Father, and you dishonor me.'),
  ('33cbbb2b-019c-5f60-aaa7-77c4e662c20a', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 50, 50, 'But I don''t seek my own glory. There is one who seeks and judges.'),
  ('1252764b-69e4-5e71-a571-c0b8acaf8d88', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 51, 51, 'Most certainly, I tell you, if a person keeps my word, he will never see death."'),
  ('e7927fc9-c987-5e52-a520-b4285e4f45cc', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 52, 52, 'Then the Jews said to him, "Now we know that you have a demon. Abraham died, and the prophets; and you say, ''If a man keeps my word, he will never taste of death.'''),
  ('91434aab-f54a-5d80-a624-197d70dabafd', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 53, 53, 'Are you greater than our father, Abraham, who died? The prophets died. Who do you make yourself out to be?"'),
  ('ce6cab8f-7b15-5bf5-a17f-265b88044d8d', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 54, 54, 'Jesus answered, "If I glorify myself, my glory is nothing. It is my Father who glorifies me, of whom you say that he is our God.'),
  ('1f744da2-4f32-5aa8-ad67-155df1f6b96c', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 55, 55, 'You have not known him, but I know him. If I said, ''I don''t know him,'' I would be like you, a liar. But I know him, and keep his word.'),
  ('45e20696-10da-5e7e-a178-6618552fe2a8', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 56, 56, 'Your father Abraham rejoiced to see my day. He saw it, and was glad."'),
  ('861c76b9-b2b7-5a03-af61-735aa722f0db', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 57, 57, 'The Jews therefore said to him, "You are not yet fifty years old, and have you seen Abraham?"'),
  ('92550310-dd05-51e6-ac1d-e61447159d0f', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 58, 58, 'Jesus said to them, "Most certainly, I tell you, before Abraham came into existence, I AM."'),
  ('631bd8bd-ee9a-5a72-a9e1-2a83f2c9987d', '3793f09a-d048-5017-a4f7-fcc085bef6c6', NULL, 59, 59, 'Therefore they took up stones to throw at him, but Jesus was hidden, and went out of the temple, having gone through the midst of them, and so passed by.'),
  ('62c959c0-0137-5bf0-ac10-d6826feee769', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 1, 1, 'As he passed by, he saw a man blind from birth.'),
  ('af2fcf99-4c0e-5aba-a54c-e01c31d2ff06', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 2, 2, 'His disciples asked him, "Rabbi, who sinned, this man or his parents, that he was born blind?"'),
  ('990a9296-1f95-5565-aef4-9f3524a26f35', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 3, 3, 'Jesus answered, "Neither did this man sin, nor his parents; but, that the works of God might be revealed in him.'),
  ('da076865-ae6c-564a-a921-ceef902625c0', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 4, 4, 'I must work the works of him who sent me, while it is day. The night is coming, when no one can work.'),
  ('c7381926-47f6-5641-a89b-280fdf50fe4c', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 5, 5, 'While I am in the world, I am the light of the world."'),
  ('53af8c3d-b3c1-5082-a92c-05d246f0b307', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 6, 6, 'When he had said this, he spat on the ground, made mud with the saliva, anointed the blind man''s eyes with the mud,'),
  ('329e89f2-c007-54f2-a5c0-af99d1e48d13', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 7, 7, 'and said to him, "Go, wash in the pool of Siloam" (which means "Sent"). So he went away, washed, and came back seeing.'),
  ('de4a581c-15c3-56a2-a553-bb5fdb0c0ce6', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 8, 8, 'The neighbors therefore, and those who saw that he was blind before, said, "Isn''t this he who sat and begged?"'),
  ('e4dc14be-1062-57d6-a601-93a27a098fa9', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 9, 9, 'Others were saying, "It is he." Still others were saying, "He looks like him." He said, "I am he."'),
  ('1fcd37e8-c743-5620-a887-52bcc9660e42', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 10, 10, 'They therefore were asking him, "How were your eyes opened?"'),
  ('a7a4c281-7065-59b2-a20c-64b0485f655c', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 11, 11, 'He answered, "A man called Jesus made mud, anointed my eyes, and said to me, ''Go to the pool of Siloam, and wash.'' So I went away and washed, and I received sight."'),
  ('68c2d35e-2c53-5e46-aa62-777d2af07bea', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 12, 12, 'Then they asked him, "Where is he?" He said, "I don''t know."'),
  ('31c8fed1-e4b6-54d3-a8ef-969600155995', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 13, 13, 'They brought him who had been blind to the Pharisees.'),
  ('18d0ecca-3bc9-5654-a4cc-c8d78686a02e', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 14, 14, 'It was a Sabbath when Jesus made the mud and opened his eyes.'),
  ('31420324-ab15-5581-aa52-bc1b45495932', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 15, 15, 'Again therefore the Pharisees also asked him how he received his sight. He said to them, "He put mud on my eyes, I washed, and I see."'),
  ('5e5e43ab-653c-5358-adf3-bade31ef5761', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 16, 16, 'Some therefore of the Pharisees said, "This man is not from God, because he doesn''t keep the Sabbath." Others said, "How can a man who is a sinner do such signs?" There was division among them.'),
  ('41ca24de-7d7b-550c-a8f5-11ec7cf7c729', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 17, 17, 'Therefore they asked the blind man again, "What do you say about him, because he opened your eyes?" He said, "He is a prophet."'),
  ('52c222fc-9101-5188-a84d-57682c5f4b17', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 18, 18, 'The Jews therefore did not believe concerning him, that he had been blind, and had received his sight, until they called the parents of him who had received his sight,'),
  ('dba95e07-a227-513c-af98-4c2591f48b16', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 19, 19, 'and asked them, "Is this your son, who you say was born blind? How then does he now see?"'),
  ('4f4a06ca-90d9-5350-a233-7fc4402fb4f5', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 20, 20, 'His parents answered them, "We know that this is our son, and that he was born blind;'),
  ('cf4efd04-6606-5607-afd3-2ccd21e5e59c', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 21, 21, 'but how he now sees, we don''t know; or who opened his eyes, we don''t know. He is of age. Ask him. He will speak for himself."'),
  ('a9af4808-0cee-5669-abec-b00d10d2c160', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 22, 22, 'His parents said these things because they feared the Jews; for the Jews had already agreed that if any man would confess him as Christ, he would be put out of the synagogue.'),
  ('004c1c2f-45a9-5a98-a168-98c4a32423b9', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 23, 23, 'Therefore his parents said, "He is of age. Ask him."'),
  ('959e1549-1423-5579-a09b-0a603548aa7d', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 24, 24, 'So they called the man who was blind a second time, and said to him, "Give glory to God. We know that this man is a sinner."'),
  ('e7d9d002-d942-5c7f-aa75-885a50d77da9', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 25, 25, 'He therefore answered, "I don''t know if he is a sinner. One thing I do know: that though I was blind, now I see."'),
  ('b1651c1c-5714-5404-aa33-129a4919ec8d', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 26, 26, 'They said to him again, "What did he do to you? How did he open your eyes?"'),
  ('ed4e6491-368f-51fb-a926-66cc1d24bbbd', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 27, 27, 'He answered them, "I told you already, and you didn''t listen. Why do you want to hear it again? You don''t also want to become his disciples, do you?"'),
  ('ab6cc44f-329d-5877-ab0a-5579b4c6d73c', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 28, 28, 'They insulted him and said, "You are his disciple, but we are disciples of Moses.'),
  ('01095def-c8c9-5930-a82d-045460baf2e9', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 29, 29, 'We know that God has spoken to Moses. But as for this man, we don''t know where he comes from."'),
  ('b03e4a7a-c16c-55b7-a1c6-26fa4800f798', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 30, 30, 'The man answered them, "How amazing! You don''t know where he comes from, yet he opened my eyes.'),
  ('1b155998-a8fb-58d7-a90b-5a88c26c09ad', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 31, 31, 'We know that God doesn''t listen to sinners, but if anyone is a worshipper of God, and does his will, he listens to him.'),
  ('ed074bbb-b651-569d-a9db-d9576c901a75', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 32, 32, 'Since the world began it has never been heard of that anyone opened the eyes of someone born blind.'),
  ('0ccb1a08-eee4-501d-ad19-78ddc9896000', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 33, 33, 'If this man were not from God, he could do nothing."'),
  ('160e47f3-045c-5479-a997-5577fba03039', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 34, 34, 'They answered him, "You were altogether born in sins, and do you teach us?" They threw him out.'),
  ('117fe5b4-f31c-57b5-a810-d6081321cfdf', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 35, 35, 'Jesus heard that they had thrown him out, and finding him, he said, "Do you believe in the Son of God?"'),
  ('8ec441b5-f96d-5f08-a07d-3a70f0493a23', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 36, 36, 'He answered, "Who is he, Lord, that I may believe in him?"'),
  ('674ab504-8946-585b-a52f-ab6f45db7ba9', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 37, 37, 'Jesus said to him, "You have both seen him, and it is he who speaks with you."'),
  ('d7d3b78b-7d37-503f-a8d6-d5a7cf8fa877', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 38, 38, 'He said, "Lord, I believe!" and he worshiped him.'),
  ('02dfb5fe-4bde-514f-a791-99b8c9f5a1a8', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 39, 39, 'Jesus said, "I came into this world for judgment, that those who don''t see may see; and that those who see may become blind."'),
  ('c423efa3-fe87-5bd8-a915-3022a98fcc91', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 40, 40, 'Those of the Pharisees who were with him heard these things, and said to him, "Are we also blind?"'),
  ('5743a55d-8687-5e04-abda-4df94cfd996d', '4907d05c-95c6-57e1-aa22-bd93b324d804', NULL, 41, 41, 'Jesus said to them, "If you were blind, you would have no sin; but now you say, ''We see.'' Therefore your sin remains.'),
  ('2655b355-c9cd-557f-af34-ec8199e012d7', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 1, 1, '"Most certainly, I tell you, one who doesn''t enter by the door into the sheep fold, but climbs up some other way, the same is a thief and a robber.'),
  ('19049026-d4ed-5e54-aaa4-3aa45a9a5e82', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 2, 2, 'But one who enters in by the door is the shepherd of the sheep.'),
  ('11dbf357-94a5-5c37-a724-540a6179fc13', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 3, 3, 'The gatekeeper opens the gate for him, and the sheep listen to his voice. He calls his own sheep by name, and leads them out.'),
  ('efc60b9e-cb5d-53aa-a16a-e295c64ef482', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 4, 4, 'Whenever he brings out his own sheep, he goes before them, and the sheep follow him, for they know his voice.'),
  ('ebaef3dd-bfe5-57a1-ab01-3f2db3e86726', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 5, 5, 'They will by no means follow a stranger, but will flee from him; for they don''t know the voice of strangers."'),
  ('464e60b6-9955-5f92-a542-be5944c2136a', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 6, 6, 'Jesus spoke this parable to them, but they didn''t understand what he was telling them.'),
  ('130c29f5-2a33-51df-aa85-9131ab4dba21', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 7, 7, 'Jesus therefore said to them again, "Most certainly, I tell you, I am the sheep''s door.'),
  ('8d50fdd4-b9e7-5143-a18a-a19737ae1a22', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 8, 8, 'All who came before me are thieves and robbers, but the sheep didn''t listen to them.'),
  ('46b1b4e6-e7ff-595b-a1c6-b7142f1fd60c', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 9, 9, 'I am the door. If anyone enters in by me, he will be saved, and will go in and go out, and will find pasture.'),
  ('4c61e4e0-2848-5c91-ad87-cf12cee3522f', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 10, 10, 'The thief only comes to steal, kill, and destroy. I came that they may have life, and may have it abundantly.'),
  ('9c2de831-0410-5cc8-a29d-11465a113d78', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 11, 11, 'I am the good shepherd. The good shepherd lays down his life for the sheep.'),
  ('244ee3ea-94dd-5cee-a1f7-b126a5ae1a36', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 12, 12, 'He who is a hired hand, and not a shepherd, who doesn''t own the sheep, sees the wolf coming, leaves the sheep, and flees. The wolf snatches the sheep, and scatters them.'),
  ('6d65e736-af3a-5219-a459-839200be9d16', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 13, 13, 'The hired hand flees because he is a hired hand, and doesn''t care for the sheep.'),
  ('8cead198-f672-54f4-a6e2-eecc716765cf', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 14, 14, 'I am the good shepherd. I know my own, and I''m known by my own;'),
  ('312bc4b5-5d77-5709-adf5-164015f732a7', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 15, 15, 'even as the Father knows me, and I know the Father. I lay down my life for the sheep.'),
  ('5345fc49-1370-5e3e-a6bf-ae84fe4d65bd', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 16, 16, 'I have other sheep, which are not of this fold. I must bring them also, and they will hear my voice. They will become one flock with one shepherd.'),
  ('726a4a18-8d70-5248-aaf0-76a2cbc54214', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 17, 17, 'Therefore the Father loves me, because I lay down my life, that I may take it again.'),
  ('a98d5735-43a4-5166-a9a2-d99dbacacd48', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 18, 18, 'No one takes it away from me, but I lay it down by myself. I have power to lay it down, and I have power to take it again. I received this commandment from my Father."'),
  ('7a7d219a-f31e-5cad-ab27-25478ef77dff', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 19, 19, 'Therefore a division arose again among the Jews because of these words.'),
  ('59ee7e52-85de-5947-a273-609556f157d3', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 20, 20, 'Many of them said, "He has a demon, and is insane! Why do you listen to him?"'),
  ('f22c1e9a-ef41-5fe5-a3da-8290ea361273', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 21, 21, 'Others said, "These are not the sayings of one possessed by a demon. It isn''t possible for a demon to open the eyes of the blind, is it?"'),
  ('b31fb30f-cb2b-507d-ad06-176634b1a698', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 22, 22, 'It was the Feast of the Dedication at Jerusalem.'),
  ('091475c0-6eab-5ff7-a1cd-7a0a5570dbdb', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 23, 23, 'It was winter, and Jesus was walking in the temple, in Solomon''s porch.'),
  ('00557722-7816-59e4-a488-36a267f1a544', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 24, 24, 'The Jews therefore came around him and said to him, "How long will you hold us in suspense? If you are the Christ, tell us plainly."'),
  ('71c0288b-5967-5200-aa4e-ef3e0f4d5661', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 25, 25, 'Jesus answered them, "I told you, and you don''t believe. The works that I do in my Father''s name, these testify about me.'),
  ('ef5dcd03-06f3-5bb4-ae06-7052329ff3f1', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 26, 26, 'But you don''t believe, because you are not of my sheep, as I told you.'),
  ('b91e72f9-c01f-5861-a911-49d5ea655f47', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 27, 27, 'My sheep hear my voice, and I know them, and they follow me.'),
  ('282cc01e-a119-5c85-a299-145cc4e94294', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 28, 28, 'I give eternal life to them. They will never perish, and no one will snatch them out of my hand.'),
  ('79a6f4cd-5ae9-539a-a705-e4b57e89c1c5', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 29, 29, 'My Father, who has given them to me, is greater than all. No one is able to snatch them out of my Father''s hand.'),
  ('38de1743-5bc1-54b6-a145-eb8fe71f7629', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 30, 30, 'I and the Father are one."'),
  ('e2159962-d5e7-5709-acd4-9f28ee4a5899', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 31, 31, 'Therefore Jews took up stones again to stone him.'),
  ('ab283278-1458-5add-adb4-82fbd9cd6961', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 32, 32, 'Jesus answered them, "I have shown you many good works from my Father. For which of those works do you stone me?"'),
  ('9cc6fd2b-96df-5f8d-ad13-597d7cf40213', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 33, 33, 'The Jews answered him, "We don''t stone you for a good work, but for blasphemy: because you, being a man, make yourself God."'),
  ('eb19714e-ae50-533d-a408-1b486629df1e', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 34, 34, 'Jesus answered them, "Isn''t it written in your law, ''I said, you are gods?'''),
  ('82abfb5d-b05c-5bcc-ad6b-c03f89e02ff9', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 35, 35, 'If he called them gods, to whom the word of God came (and the Scripture can''t be broken),'),
  ('ab51137e-f394-5a17-a57a-456b439ed1e3', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 36, 36, 'do you say of him whom the Father sanctified and sent into the world, ''You blaspheme,'' because I said, ''I am the Son of God?'''),
  ('9004c588-5d06-5054-ad1b-7e8f3d07ffec', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 37, 37, 'If I don''t do the works of my Father, don''t believe me.'),
  ('996059af-51a0-5a14-ada1-161b7c2e3865', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 38, 38, 'But if I do them, though you don''t believe me, believe the works; that you may know and believe that the Father is in me, and I in the Father."'),
  ('558cc694-97e1-51bd-a40f-67a21dceb10c', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 39, 39, 'They sought again to seize him, and he went out of their hand.'),
  ('be682742-f56c-542c-ac28-7a286d65cc23', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 40, 40, 'He went away again beyond the Jordan into the place where John was baptizing at first, and there he stayed.'),
  ('d9be5ff5-5d92-5e14-a2a1-b98f9cda2138', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 41, 41, 'Many came to him. They said, "John indeed did no sign, but everything that John said about this man is true."'),
  ('dba6425a-65a9-56b9-a890-01d23e0f60c4', '484e4f2b-3e89-5a90-a3ee-1aba13dbd23a', NULL, 42, 42, 'Many believed in him there.'),
  ('1090c527-117a-583a-a575-8be805553105', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 1, 1, 'Now a certain man was sick, Lazarus from Bethany, of the village of Mary and her sister, Martha.'),
  ('3d26a7d8-e65a-5765-a957-864190ecf2d4', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 2, 2, 'It was that Mary who had anointed the Lord with ointment, and wiped his feet with her hair, whose brother, Lazarus, was sick.'),
  ('d4fee942-727e-5164-a05f-88e528a4f879', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 3, 3, 'The sisters therefore sent to him, saying, "Lord, behold, he for whom you have great affection is sick."'),
  ('e34d1a53-e43e-5b14-ab9a-ad2fcbc7a696', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 4, 4, 'But when Jesus heard it, he said, "This sickness is not to death, but for the glory of God, that God''s Son may be glorified by it."'),
  ('e03a4a34-3af6-59f0-afe2-58e5864d6eee', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 5, 5, 'Now Jesus loved Martha, and her sister, and Lazarus.'),
  ('f275bf41-6fc1-56f6-acc1-f6dccf14b284', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 6, 6, 'When therefore he heard that he was sick, he stayed two days in the place where he was.'),
  ('6228aee1-43dd-54f8-a2c2-4610b7b577e2', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 7, 7, 'Then after this he said to the disciples, "Let''s go into Judea again."'),
  ('167bd27f-2fca-53bd-a7f3-eae82089826f', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 8, 8, 'The disciples told him, "Rabbi, the Jews were just trying to stone you, and are you going there again?"'),
  ('6abe5256-8a26-5621-a3a5-85f5a2e32564', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 9, 9, 'Jesus answered, "Aren''t there twelve hours of daylight? If a man walks in the day, he doesn''t stumble, because he sees the light of this world.'),
  ('d3781572-ba4d-5200-afe1-186844da824c', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 10, 10, 'But if a man walks in the night, he stumbles, because the light isn''t in him."'),
  ('9fc5a829-2383-5c6b-a70b-173896225494', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 11, 11, 'He said these things, and after that, he said to them, "Our friend, Lazarus, has fallen asleep, but I am going so that I may awake him out of sleep."'),
  ('cf158ce8-f224-59f0-a049-3fd39d7d6a81', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 12, 12, 'The disciples therefore said, "Lord, if he has fallen asleep, he will recover."'),
  ('6dde2701-8fc3-5e69-a612-499705528e52', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 13, 13, 'Now Jesus had spoken of his death, but they thought that he spoke of taking rest in sleep.'),
  ('03113856-2ddd-568b-ac94-d42de17470b4', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 14, 14, 'So Jesus said to them plainly then, "Lazarus is dead.'),
  ('1a219f9f-27a5-5c0b-a0da-c6617b1b688f', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 15, 15, 'I am glad for your sakes that I was not there, so that you may believe. Nevertheless, let''s go to him."'),
  ('3403bb8b-62b3-5421-a44c-e4711d6edfda', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 16, 16, 'Thomas therefore, who is called Didymus, said to his fellow disciples, "Let''s go also, that we may die with him."'),
  ('7596e73c-cb26-567a-a63e-8b281d2376f4', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 17, 17, 'So when Jesus came, he found that he had been in the tomb four days already.'),
  ('39eca2f1-056f-5f14-a75b-0c9fdaa3a980', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 18, 18, 'Now Bethany was near Jerusalem, about fifteen stadia away.'),
  ('6f02478e-f87e-5df5-a497-9a27ce049693', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 19, 19, 'Many of the Jews had joined the women around Martha and Mary, to console them concerning their brother.'),
  ('ac9a9b24-fba3-5786-ae2d-6da23db16542', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 20, 20, 'Then when Martha heard that Jesus was coming, she went and met him, but Mary stayed in the house.'),
  ('3a479b0a-163f-5cb5-a0aa-9ac628cdff7d', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 21, 21, 'Therefore Martha said to Jesus, "Lord, if you would have been here, my brother wouldn''t have died.'),
  ('8dcda1b3-328e-53c6-ae14-b7187358f344', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 22, 22, 'Even now I know that, whatever you ask of God, God will give you."'),
  ('0046060f-d905-5c22-aa95-436d5f99cb25', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 23, 23, 'Jesus said to her, "Your brother will rise again."'),
  ('fb159fe3-4a05-5d97-a71b-098e2599bc87', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 24, 24, 'Martha said to him, "I know that he will rise again in the resurrection at the last day."'),
  ('cd1447d1-1c52-59c6-ab02-5f4cdb0784d0', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 25, 25, 'Jesus said to her, "I am the resurrection and the life. He who believes in me will still live, even if he dies.'),
  ('c1d6cdbf-f2f5-504a-a648-451332f3fb83', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 26, 26, 'Whoever lives and believes in me will never die. Do you believe this?"'),
  ('ebbb7ad5-58d7-52c3-aadb-c084831a0f29', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 27, 27, 'She said to him, "Yes, Lord. I have come to believe that you are the Christ, God''s Son, he who comes into the world."'),
  ('a34d551c-4896-506a-ad28-9b20716082f4', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 28, 28, 'When she had said this, she went away, and called Mary, her sister, secretly, saying, "The Teacher is here, and is calling you."'),
  ('25d11652-1b89-5edb-a8c9-222839fcf57e', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 29, 29, 'When she heard this, she arose quickly, and went to him.'),
  ('6a8d0261-b678-5b91-ad13-1fd55600280e', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 30, 30, 'Now Jesus had not yet come into the village, but was in the place where Martha met him.'),
  ('b7161b51-6661-53ba-ab71-ed5b5c977968', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 31, 31, 'Then the Jews who were with her in the house, and were consoling her, when they saw Mary, that she rose up quickly and went out, followed her, saying, "She is going to the tomb to weep there."'),
  ('2bc6fa05-5d04-5378-a785-870c83057ba7', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 32, 32, 'Therefore when Mary came to where Jesus was, and saw him, she fell down at his feet, saying to him, "Lord, if you would have been here, my brother wouldn''t have died."'),
  ('161d9865-01a4-5460-a351-6170dfd42ecf', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 33, 33, 'When Jesus therefore saw her weeping, and the Jews weeping who came with her, he groaned in the spirit, and was troubled,'),
  ('d48abdea-8390-5d46-a71f-dd937dcbf386', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 34, 34, 'and said, "Where have you laid him?" They told him, "Lord, come and see."'),
  ('8aa197da-77c5-5618-af56-85b25e24f00d', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 35, 35, 'Jesus wept.'),
  ('7bdba1ec-5419-56b8-a063-380feaee825e', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 36, 36, 'The Jews therefore said, "See how much affection he had for him!"'),
  ('fa3b3d42-3aa7-5651-a054-2d3bd0122dcb', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 37, 37, 'Some of them said, "Couldn''t this man, who opened the eyes of him who was blind, have also kept this man from dying?"'),
  ('c35a8c69-5751-596e-af09-eb97d42b25e5', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 38, 38, 'Jesus therefore, again groaning in himself, came to the tomb. Now it was a cave, and a stone lay against it.'),
  ('4e87f976-4ae3-5023-a433-8b572d0aeab4', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 39, 39, 'Jesus said, "Take away the stone." Martha, the sister of him who was dead, said to him, "Lord, by this time there is a stench, for he has been dead four days."'),
  ('9ab2ace1-ba0e-56f4-a449-8b5484282f3f', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 40, 40, 'Jesus said to her, "Didn''t I tell you that if you believed, you would see God''s glory?"'),
  ('b5bafb22-ee98-5f38-af77-202d23261fa7', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 41, 41, 'So they took away the stone from the place where the dead man was lying. Jesus lifted up his eyes, and said, "Father, I thank you that you listened to me.'),
  ('7e0473e8-cbf7-550a-a4ae-3b9016e3a3d4', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 42, 42, 'I know that you always listen to me, but because of the multitude that stands around I said this, that they may believe that you sent me."'),
  ('dd869d32-2609-5f24-a8ce-80d0898fa0ae', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 43, 43, 'When he had said this, he cried with a loud voice, "Lazarus, come out!"'),
  ('a4f55913-6bce-5fd6-ab25-80f5e5ff501e', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 44, 44, 'He who was dead came out, bound hand and foot with wrappings, and his face was wrapped around with a cloth. Jesus said to them, "Free him, and let him go."'),
  ('b7b9e7f2-7d7b-5f35-abb4-e67dd54f5ab9', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 45, 45, 'Therefore many of the Jews, who came to Mary and saw what Jesus did, believed in him.'),
  ('2702836f-e407-57a1-af9a-9366489e7fdf', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 46, 46, 'But some of them went away to the Pharisees, and told them the things which Jesus had done.'),
  ('d5995072-a764-5fd2-a4de-b9615283da32', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 47, 47, 'The chief priests therefore and the Pharisees gathered a council, and said, "What are we doing? For this man does many signs.'),
  ('2c4dea00-8ef1-53d4-a45d-f3603389ecbf', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 48, 48, 'If we leave him alone like this, everyone will believe in him, and the Romans will come and take away both our place and our nation."'),
  ('3a40c002-e234-5d43-ada9-16da7ae2b01e', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 49, 49, 'But a certain one of them, Caiaphas, being high priest that year, said to them, "You know nothing at all,'),
  ('47a61d42-e6f4-5863-af96-310bad83eab0', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 50, 50, 'nor do you consider that it is advantageous for us that one man should die for the people, and that the whole nation not perish."'),
  ('400eb1d6-615a-5aaf-a8e0-ef175438c054', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 51, 51, 'Now he didn''t say this of himself, but being high priest that year, he prophesied that Jesus would die for the nation,'),
  ('031bde4e-5681-5741-a5be-1697261c9923', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 52, 52, 'and not for the nation only, but that he might also gather together into one the children of God who are scattered abroad.'),
  ('7ebd5cef-8f4e-56cb-ab85-a35b0046b8ec', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 53, 53, 'So from that day forward they took counsel that they might put him to death.'),
  ('310367e5-b1f9-5be4-a512-bfcab8dffcd7', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 54, 54, 'Jesus therefore walked no more openly among the Jews, but departed from there into the country near the wilderness, to a city called Ephraim. He stayed there with his disciples.'),
  ('d1fb1279-6728-5486-a904-0502da297c19', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 55, 55, 'Now the Passover of the Jews was at hand. Many went up from the country to Jerusalem before the Passover, to purify themselves.'),
  ('6f173ba6-ab21-551b-a9c0-4dce9cf0bce8', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 56, 56, 'Then they sought for Jesus and spoke one with another, as they stood in the temple, "What do you think--that he isn''t coming to the feast at all?"'),
  ('af107e92-01e2-555f-ae0d-cb2c4f8a96f8', 'a738dc59-4498-5dd9-a022-91d9bfb49f7d', NULL, 57, 57, 'Now the chief priests and the Pharisees had commanded that if anyone knew where he was, he should report it, that they might seize him.'),
  ('4711339e-e34f-50dc-a496-c1202206da9b', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 1, 1, 'Then six days before the Passover, Jesus came to Bethany, where Lazarus was, who had been dead, whom he raised from the dead.'),
  ('42bcb6e6-c4f1-5ace-a515-7f189756fe75', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 2, 2, 'So they made him a supper there. Martha served, but Lazarus was one of those who sat at the table with him.'),
  ('d6ec63b9-8707-5425-a008-ec03264585de', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 3, 3, 'Mary, therefore, took a pound of ointment of pure nard, very precious, and anointed the feet of Jesus, and wiped his feet with her hair. The house was filled with the fragrance of the ointment.'),
  ('52f3ffe3-a039-5ffc-a4ed-9b6262a65bad', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 4, 4, 'Then Judas Iscariot, Simon''s son, one of his disciples, who would betray him, said,'),
  ('fc300e28-fdc4-56a4-a7dd-15efbc6fd4ae', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 5, 5, '"Why wasn''t this ointment sold for three hundred denarii, and given to the poor?"'),
  ('e7652e4b-5f44-50f4-add0-66293a2829ce', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 6, 6, 'Now he said this, not because he cared for the poor, but because he was a thief, and having the money box, used to steal what was put into it.'),
  ('28683fc6-d325-5daf-adc3-affe5dbd8ade', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 7, 7, 'But Jesus said, "Leave her alone. She has kept this for the day of my burial.'),
  ('9fef8da1-9481-5070-a715-3305b3aa91ae', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 8, 8, 'For you always have the poor with you, but you don''t always have me."'),
  ('066c1d87-24c8-5095-aa2e-68282559f863', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 9, 9, 'A large crowd therefore of the Jews learned that he was there, and they came, not for Jesus'' sake only, but that they might see Lazarus also, whom he had raised from the dead.'),
  ('05dbe457-64ae-5fe6-a999-061af3284043', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 10, 10, 'But the chief priests conspired to put Lazarus to death also,'),
  ('cc8682c1-402c-56ee-ae43-07b72c93be93', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 11, 11, 'because on account of him many of the Jews went away and believed in Jesus.'),
  ('79e03a47-ffa7-5704-ac3f-e6d62b6ae8c2', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 12, 12, 'On the next day a great multitude had come to the feast. When they heard that Jesus was coming to Jerusalem,'),
  ('ce2a273b-8e76-5fe6-a895-127a37ecac35', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 13, 13, 'they took the branches of the palm trees, and went out to meet him, and cried out, "Hosanna! Blessed is he who comes in the name of the Lord, the King of Israel!"'),
  ('921460cb-3d1c-577e-ab0f-9cdeadc8839f', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 14, 14, 'Jesus, having found a young donkey, sat on it. As it is written,'),
  ('6b353d22-4806-5a50-a598-e69eb41f5002', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 15, 15, '"Don''t be afraid, daughter of Zion. Behold, your King comes, sitting on a donkey''s colt."'),
  ('5b7e9de5-2f02-5e14-a32b-8353f2e88793', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 16, 16, 'His disciples didn''t understand these things at first, but when Jesus was glorified, then they remembered that these things were written about him, and that they had done these things to him.'),
  ('3348ec59-d742-59e0-a0a1-d81d0d64aea3', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 17, 17, 'The multitude therefore that was with him when he called Lazarus out of the tomb, and raised him from the dead, was testifying about it.'),
  ('e6fa7ee5-3873-5242-ad3e-413d03f756ea', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 18, 18, 'For this cause also the multitude went and met him, because they heard that he had done this sign.'),
  ('0e0c74c2-08e1-5078-a635-1623a1add5b4', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 19, 19, 'The Pharisees therefore said among themselves, "See how you accomplish nothing. Behold, the world has gone after him."'),
  ('f8483414-bdbf-5b35-a23e-b3a85beccffb', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 20, 20, 'Now there were certain Greeks among those that went up to worship at the feast.'),
  ('d2312bc5-3254-5b7e-a27a-a88fadde4c12', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 21, 21, 'These, therefore, came to Philip, who was from Bethsaida of Galilee, and asked him, saying, "Sir, we want to see Jesus."'),
  ('4f5ed0f5-a46c-5d73-a2cf-23c1270f859b', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 22, 22, 'Philip came and told Andrew, and in turn, Andrew came with Philip, and they told Jesus.'),
  ('4721c23f-57ff-56b8-af0d-49b3a006afed', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 23, 23, 'Jesus answered them, "The time has come for the Son of Man to be glorified.'),
  ('1adb8478-62d6-55bf-a926-fea62bfa5190', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 24, 24, 'Most certainly I tell you, unless a grain of wheat falls into the earth and dies, it remains by itself alone. But if it dies, it bears much fruit.'),
  ('47b105cd-9cfb-5f38-aaef-ea8b95204ea4', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 25, 25, 'He who loves his life will lose it. He who hates his life in this world will keep it to eternal life.'),
  ('8f0976ba-55f8-5ac9-ac9d-7e7462e4fe9d', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 26, 26, 'If anyone serves me, let him follow me. Where I am, there will my servant also be. If anyone serves me, the Father will honor him.'),
  ('753522ce-bd93-5f0d-aa1e-55c4c0b0b5de', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 27, 27, '"Now my soul is troubled. What shall I say? ''Father, save me from this time?'' But for this cause I came to this time.'),
  ('e6e96ffc-b397-55c7-ad63-d35fa255b9c0', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 28, 28, 'Father, glorify your name!" Then there came a voice out of the sky, saying, "I have both glorified it, and will glorify it again."'),
  ('692865ae-81b6-5587-a101-ffe597c5e142', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 29, 29, 'The multitude therefore, who stood by and heard it, said that it had thundered. Others said, "An angel has spoken to him."'),
  ('189f02e8-0926-5bb2-a243-84352c5a1b0b', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 30, 30, 'Jesus answered, "This voice hasn''t come for my sake, but for your sakes.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('799bf279-84cf-5aba-a066-26f3dba7bb7c', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 31, 31, 'Now is the judgment of this world. Now the prince of this world will be cast out.'),
  ('550cb4a2-d81a-595b-ace7-47dc9e5a056a', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 32, 32, 'And I, if I am lifted up from the earth, will draw all people to myself."'),
  ('5a15b922-43c2-53f7-af93-9272ae7b2b85', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 33, 33, 'But he said this, signifying by what kind of death he should die.'),
  ('831597f5-1113-511c-a1ef-69fe97cc200c', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 34, 34, 'The multitude answered him, "We have heard out of the law that the Christ remains forever. How do you say, ''The Son of Man must be lifted up?'' Who is this Son of Man?"'),
  ('893ecc2b-5505-5196-a435-e7c3163a3bac', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 35, 35, 'Jesus therefore said to them, "Yet a little while the light is with you. Walk while you have the light, that darkness doesn''t overtake you. He who walks in the darkness doesn''t know where he is going.'),
  ('8013d2ec-f1ac-5984-ab6e-819da9e31b01', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 36, 36, 'While you have the light, believe in the light, that you may become children of light." Jesus said these things, and he departed and hid himself from them.'),
  ('0c4aaf5c-699c-5eb3-a544-21a56b6b8347', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 37, 37, 'But though he had done so many signs before them, yet they didn''t believe in him,'),
  ('6736b490-939f-5bb6-a519-a897efa3026d', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 38, 38, 'that the word of Isaiah the prophet might be fulfilled, which he spoke, "Lord, who has believed our report? To whom has the arm of the Lord been revealed?"'),
  ('477f5123-1463-5866-ab9f-69735199b99a', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 39, 39, 'For this cause they couldn''t believe, for Isaiah said again,'),
  ('8fe07314-0dea-570d-a049-56fdf069b7aa', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 40, 40, '"He has blinded their eyes and he hardened their heart, lest they should see with their eyes, and perceive with their heart, and would turn, and I would heal them."'),
  ('000b0c52-1e62-5cfe-a106-e93809e4e9ed', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 41, 41, 'Isaiah said these things when he saw his glory, and spoke of him.'),
  ('866926cc-c17c-524d-ad0f-c31792504b0a', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 42, 42, 'Nevertheless even of the rulers many believed in him, but because of the Pharisees they didn''t confess it, so that they wouldn''t be put out of the synagogue,'),
  ('1b106dd2-6076-53f1-a3da-2b36b9bf12ea', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 43, 43, 'for they loved men''s praise more than God''s praise.'),
  ('5ddc2f0c-5ca4-5211-a3e0-de7b282ade84', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 44, 44, 'Jesus cried out and said, "Whoever believes in me, believes not in me, but in him who sent me.'),
  ('ef762288-9829-5a4f-ac51-3fc978ff572d', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 45, 45, 'He who sees me sees him who sent me.'),
  ('14b8064f-23e9-5246-a94b-72a9b3e01a5b', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 46, 46, 'I have come as a light into the world, that whoever believes in me may not remain in the darkness.'),
  ('bdd49ae0-5f08-5711-aa58-b7f325e95a2f', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 47, 47, 'If anyone listens to my sayings, and doesn''t believe, I don''t judge him. For I came not to judge the world, but to save the world.'),
  ('31af1056-6578-5742-af28-6eecaf239033', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 48, 48, 'He who rejects me, and doesn''t receive my sayings, has one who judges him. The word that I spoke, the same will judge him in the last day.'),
  ('d293be1a-2aab-5080-a6e0-3c1ec7803699', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 49, 49, 'For I spoke not from myself, but the Father who sent me, he gave me a commandment, what I should say, and what I should speak.'),
  ('66b9e5a8-0446-52d0-aa1f-3f3cf95f5dba', 'beee9809-a32f-5fa7-a05b-0480642e09c4', NULL, 50, 50, 'I know that his commandment is eternal life. The things therefore which I speak, even as the Father has said to me, so I speak."'),
  ('4af25b5d-98b2-5835-a6fd-f571e953b84c', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 1, 1, 'Now before the feast of the Passover, Jesus, knowing that his time had come that he would depart from this world to the Father, having loved his own who were in the world, he loved them to the end.'),
  ('f33f5b2c-7187-5c97-a225-2a857d417a97', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 2, 2, 'During supper, the devil having already put into the heart of Judas Iscariot, Simon''s son, to betray him,'),
  ('9bde4e0c-bcbb-5ffb-ac31-7041f7c3d3e2', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 3, 3, 'Jesus, knowing that the Father had given all things into his hands, and that he came forth from God, and was going to God,'),
  ('7e480045-80cb-58a3-aea2-a6c24cf0709c', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 4, 4, 'arose from supper, and laid aside his outer garments. He took a towel, and wrapped a towel around his waist.'),
  ('680f3e4c-463e-5de6-aebb-4d91ca5267f9', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 5, 5, 'Then he poured water into the basin, and began to wash the disciples'' feet, and to wipe them with the towel that was wrapped around him.'),
  ('ebf77ac3-e051-5b49-a7f3-ad073bfa0ae8', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 6, 6, 'Then he came to Simon Peter. He said to him, "Lord, do you wash my feet?"'),
  ('9b204bb2-d158-532c-a739-1f1c10ae4520', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 7, 7, 'Jesus answered him, "You don''t know what I am doing now, but you will understand later."'),
  ('5791af55-966e-5b6c-a391-5191f4dd9843', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 8, 8, 'Peter said to him, "You will never wash my feet!" Jesus answered him, "If I don''t wash you, you have no part with me."'),
  ('b0d5ad91-0b66-5f9a-ae70-3fcce78a96fc', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 9, 9, 'Simon Peter said to him, "Lord, not my feet only, but also my hands and my head!"'),
  ('860e99ce-0f2f-57fe-adaf-6e748e98d90f', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 10, 10, 'Jesus said to him, "Someone who has bathed only needs to have his feet washed, but is completely clean. You are clean, but not all of you."'),
  ('2414792e-6f88-5463-acff-9553a267336c', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 11, 11, 'For he knew him who would betray him, therefore he said, "You are not all clean."'),
  ('2922462d-bec8-535b-af0d-2408fabf4534', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 12, 12, 'So when he had washed their feet, put his outer garment back on, and sat down again, he said to them, "Do you know what I have done to you?'),
  ('54645491-3188-56a0-a9e7-c079d2c18746', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 13, 13, 'You call me, ''Teacher'' and ''Lord.'' You say so correctly, for so I am.'),
  ('52c208b3-ed96-5767-a5df-66c10c477808', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 14, 14, 'If I then, the Lord and the Teacher, have washed your feet, you also ought to wash one another''s feet.'),
  ('bb4792ee-905b-562f-a68d-3d579efc86d2', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 15, 15, 'For I have given you an example, that you also should do as I have done to you.'),
  ('6e7577ab-17e6-5bf0-ad39-306f84fc7a8d', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 16, 16, 'Most certainly I tell you, a servant is not greater than his lord, neither one who is sent greater than he who sent him.'),
  ('7c6987a5-9965-5574-a622-7bbd1722f53b', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 17, 17, 'If you know these things, blessed are you if you do them.'),
  ('66f364ba-3703-5c5c-a50f-5398ac3ad9b9', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 18, 18, 'I don''t speak concerning all of you. I know whom I have chosen. But that the Scripture may be fulfilled, ''He who eats bread with me has lifted up his heel against me.'''),
  ('feddd92d-70c5-5882-a64f-c043e57e895c', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 19, 19, 'From now on, I tell you before it happens, that when it happens, you may believe that I am he.'),
  ('20d8d934-71ab-5c68-a8fe-e7d21b933c59', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 20, 20, 'Most certainly I tell you, he who receives whomever I send, receives me; and he who receives me, receives him who sent me."'),
  ('933f54e5-f8c1-581f-acaa-5a183dda09c1', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 21, 21, 'When Jesus had said this, he was troubled in spirit, and testified, "Most certainly I tell you that one of you will betray me."'),
  ('30956ef7-e3b3-5412-a05b-ebf75c756fb6', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 22, 22, 'The disciples looked at one another, perplexed about whom he spoke.'),
  ('0adf2133-1352-5b89-abfb-33992fc3850c', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 23, 23, 'One of his disciples, whom Jesus loved, was at the table, leaning against Jesus'' breast.'),
  ('454232b3-87b1-5ff2-a64d-6e7e48d47172', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 24, 24, 'Simon Peter therefore beckoned to him, and said to him, "Tell us who it is of whom he speaks."'),
  ('ffad6745-8d21-5e55-a0c9-7bf2ece09c93', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 25, 25, 'He, leaning back, as he was, on Jesus'' breast, asked him, "Lord, who is it?"'),
  ('2810e38e-0945-5e60-a80a-60cc4ea12edf', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 26, 26, 'Jesus therefore answered, "It is he to whom I will give this piece of bread when I have dipped it." So when he had dipped the piece of bread, he gave it to Judas, the son of Simon Iscariot.'),
  ('9930f38e-371a-5f55-ae75-5bd4fbdd2f9e', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 27, 27, 'After the piece of bread, then Satan entered into him. Then Jesus said to him, "What you do, do quickly."'),
  ('8db09d91-cfaf-58c8-ad92-884c7a13b6eb', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 28, 28, 'Now no man at the table knew why he said this to him.'),
  ('47917f72-9097-5b0a-aaa8-cf79634fe049', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 29, 29, 'For some thought, because Judas had the money box, that Jesus said to him, "Buy what things we need for the feast," or that he should give something to the poor.'),
  ('a9212df5-fabb-5b30-abe8-ff92d69d4d54', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 30, 30, 'Therefore, having received that morsel, he went out immediately. It was night.'),
  ('0c1c1813-113f-50ea-a72b-2c5a396cd079', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 31, 31, 'When he had gone out, Jesus said, "Now the Son of Man has been glorified, and God has been glorified in him.'),
  ('dd389711-b8fc-513f-a77d-09e70b297e83', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 32, 32, 'If God has been glorified in him, God will also glorify him in himself, and he will glorify him immediately.'),
  ('d9d7c98c-c4e6-542d-a4b0-3e161afa229c', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 33, 33, 'Little children, I will be with you a little while longer. You will seek me, and as I said to the Jews, ''Where I am going, you can''t come,'' so now I tell you.'),
  ('12b0132e-bcc3-5c92-a5a7-d7b82dc3f258', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 34, 34, 'A new commandment I give to you, that you love one another, just like I have loved you; that you also love one another.'),
  ('88f387b1-c116-5977-a342-66cba76edc57', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 35, 35, 'By this everyone will know that you are my disciples, if you have love for one another."'),
  ('f78820a6-2585-5aab-a3b5-fd52cd998418', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 36, 36, 'Simon Peter said to him, "Lord, where are you going?" Jesus answered, "Where I am going, you can''t follow now, but you will follow afterwards."'),
  ('dc79743d-2334-5579-a0de-996f3970be38', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 37, 37, 'Peter said to him, "Lord, why can''t I follow you now? I will lay down my life for you."'),
  ('4c15db04-2206-5b6d-a8de-7cba31356b78', 'b1490bde-93aa-5484-a6a3-b897829048d4', NULL, 38, 38, 'Jesus answered him, "Will you lay down your life for me? Most certainly I tell you, the rooster won''t crow until you have denied me three times.'),
  ('7077968f-0e40-572d-a289-3d75d284c1fa', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 1, 1, '"Don''t let your heart be troubled. Believe in God. Believe also in me.'),
  ('99e3b702-755d-5cca-a225-74c44b24f4b1', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 2, 2, 'In my Father''s house are many homes. If it weren''t so, I would have told you. I am going to prepare a place for you.'),
  ('6ef16e36-0dec-5941-ae64-fd6edb8e9c8b', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 3, 3, 'If I go and prepare a place for you, I will come again, and will receive you to myself; that where I am, you may be there also.'),
  ('db8bcb24-860e-58e1-a200-6171c3667add', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 4, 4, 'Where I go, you know, and you know the way."'),
  ('15919a79-bc26-5188-a200-83dbe6810566', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 5, 5, 'Thomas said to him, "Lord, we don''t know where you are going. How can we know the way?"'),
  ('2aed5357-151c-5720-aa08-782adc8e02b2', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 6, 6, 'Jesus said to him, "I am the way, the truth, and the life. No one comes to the Father, except through me.'),
  ('2ee91cc5-e7d1-525c-aed8-5e4addaa8331', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 7, 7, 'If you had known me, you would have known my Father also. From now on, you know him, and have seen him."'),
  ('d325ab37-de3e-5760-a8dc-655ccf7c6f19', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 8, 8, 'Philip said to him, "Lord, show us the Father, and that will be enough for us."'),
  ('c23d9d1e-2056-5854-a407-d56a2cf725f0', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 9, 9, 'Jesus said to him, "Have I been with you such a long time, and do you not know me, Philip? He who has seen me has seen the Father. How do you say, ''Show us the Father?'''),
  ('4c8b987d-f1d7-5412-a3b4-222da0ece4a6', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 10, 10, 'Don''t you believe that I am in the Father, and the Father in me? The words that I tell you, I speak not from myself; but the Father who lives in me does his works.'),
  ('fecd33fb-8d62-5b96-ab03-934810db19fc', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 11, 11, 'Believe me that I am in the Father, and the Father in me; or else believe me for the very works'' sake.'),
  ('91156856-e5ac-56e0-aac0-d2bd2969a798', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 12, 12, 'Most certainly I tell you, he who believes in me, the works that I do, he will do also; and he will do greater works than these, because I am going to my Father.'),
  ('06108772-370c-5801-acd9-23e8024e9ba8', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 13, 13, 'Whatever you will ask in my name, that will I do, that the Father may be glorified in the Son.'),
  ('6a094737-5482-540a-ad20-834ca3cf10a6', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 14, 14, 'If you will ask anything in my name, I will do it.'),
  ('2be5b74c-9c0a-5f0c-ab45-a7b2377f6c27', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 15, 15, 'If you love me, keep my commandments.'),
  ('d5ae1ff5-c960-5f52-afaf-8f5f5f60cc83', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 16, 16, 'I will pray to the Father, and he will give you another Counselor, that he may be with you forever,--'),
  ('c0755e7f-7460-5bf7-a858-b318f91f7c8b', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 17, 17, 'the Spirit of truth, whom the world can''t receive; for it doesn''t see him, neither knows him. You know him, for he lives with you, and will be in you.'),
  ('1482d6ff-f09c-5c6f-afbf-8a325027fe7f', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 18, 18, 'I will not leave you orphans. I will come to you.'),
  ('a70d1d18-ed9e-541e-a211-8ee6e37a4b86', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 19, 19, 'Yet a little while, and the world will see me no more; but you will see me. Because I live, you will live also.'),
  ('24fb30cf-202d-5b4f-aca5-20da6ee97d40', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 20, 20, 'In that day you will know that I am in my Father, and you in me, and I in you.'),
  ('bc956ae7-7f5b-50b8-aef3-7efa5cbff91d', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 21, 21, 'One who has my commandments, and keeps them, that person is one who loves me. One who loves me will be loved by my Father, and I will love him, and will reveal myself to him."'),
  ('b4557a2b-47ef-50b2-a18a-810926e993f7', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 22, 22, 'Judas (not Iscariot) said to him, "Lord, what has happened that you are about to reveal yourself to us, and not to the world?"'),
  ('0bc2a1de-5a1b-5b66-a9b9-0c5dc4c5ac05', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 23, 23, 'Jesus answered him, "If a man loves me, he will keep my word. My Father will love him, and we will come to him, and make our home with him.'),
  ('a7e38de2-e719-5058-a2b7-9574766c6d73', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 24, 24, 'He who doesn''t love me doesn''t keep my words. The word which you hear isn''t mine, but the Father''s who sent me.'),
  ('2ada2adc-5621-5756-a392-34a06fd5086a', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 25, 25, 'I have said these things to you, while still living with you.'),
  ('73c2abea-94ec-56f5-aacb-08effbfa43ea', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 26, 26, 'But the Counselor, the Holy Spirit, whom the Father will send in my name, he will teach you all things, and will remind you of all that I said to you.'),
  ('18e4c136-c1e3-5747-ad8f-6978958b7704', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 27, 27, 'Peace I leave with you. My peace I give to you; not as the world gives, give I to you. Don''t let your heart be troubled, neither let it be fearful.'),
  ('e32a6956-977a-5e8e-a19b-fdbc60a6531b', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 28, 28, 'You heard how I told you, ''I go away, and I come to you.'' If you loved me, you would have rejoiced, because I said ''I am going to my Father;'' for the Father is greater than I.'),
  ('5fd7c20d-cb6d-5ff6-a2b2-ff057ae7b074', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 29, 29, 'Now I have told you before it happens so that, when it happens, you may believe.'),
  ('470c0d34-d7a5-5131-a28c-b7ec7b2151a6', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 30, 30, 'I will no more speak much with you, for the prince of the world comes, and he has nothing in me.'),
  ('cf192b96-e003-519a-aca7-c2977b0c5fa7', 'dd87861b-2064-5990-a90e-85383bc94cd6', NULL, 31, 31, 'But that the world may know that I love the Father, and as the Father commanded me, even so I do. Arise, let us go from here.'),
  ('caf24e38-ac78-5dfc-a395-a0e53497cf6d', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 1, 1, '"I am the true vine, and my Father is the farmer.'),
  ('80a7ae33-a7f6-5b4d-a2e3-904a3296e025', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 2, 2, 'Every branch in me that doesn''t bear fruit, he takes away. Every branch that bears fruit, he prunes, that it may bear more fruit.'),
  ('2105d356-ccd8-5f33-a80f-cd73feea0a36', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 3, 3, 'You are already pruned clean because of the word which I have spoken to you.'),
  ('780ce1ae-da0a-5c1e-ab2a-9f77c12f5edd', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 4, 4, 'Remain in me, and I in you. As the branch can''t bear fruit by itself, unless it remains in the vine, so neither can you, unless you remain in me.'),
  ('a9cb36e0-adc0-5311-aa62-66740cb9d0f6', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 5, 5, 'I am the vine. You are the branches. He who remains in me, and I in him, the same bears much fruit, for apart from me you can do nothing.'),
  ('f283fe56-7f70-5d1e-a044-5f652168b69b', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 6, 6, 'If a man doesn''t remain in me, he is thrown out as a branch, and is withered; and they gather them, throw them into the fire, and they are burned.'),
  ('0af9d87e-6396-5ec1-a073-bda0ce67e9be', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 7, 7, 'If you remain in me, and my words remain in you, you will ask whatever you desire, and it will be done for you.'),
  ('d0202495-46cd-5f94-ad02-cffd156e6646', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 8, 8, '"In this is my Father glorified, that you bear much fruit; and so you will be my disciples.'),
  ('4d5f6d57-eae2-5573-a41b-657e463a6ac2', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 9, 9, 'Even as the Father has loved me, I also have loved you. Remain in my love.'),
  ('694e3e48-0243-5a04-ab75-e7461d378d87', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 10, 10, 'If you keep my commandments, you will remain in my love; even as I have kept my Father''s commandments, and remain in his love.'),
  ('1e2f8523-43e4-59cf-a64b-39dc2f3734a5', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 11, 11, 'I have spoken these things to you, that my joy may remain in you, and that your joy may be made full.'),
  ('3768a5da-9336-52c7-a445-454a57e412c1', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 12, 12, '"This is my commandment, that you love one another, even as I have loved you.'),
  ('05cbe09c-810f-55de-a058-f2471069de27', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 13, 13, 'Greater love has no one than this, that someone lay down his life for his friends.'),
  ('9f0c56bf-97a4-5b76-a359-ae39a33abb0b', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 14, 14, 'You are my friends, if you do whatever I command you.'),
  ('f5575b43-fc94-5254-a7c5-64d9a6ddbbb2', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 15, 15, 'No longer do I call you servants, for the servant doesn''t know what his lord does. But I have called you friends, for everything that I heard from my Father, I have made known to you.'),
  ('f04cc5d7-49fe-5b7a-aa4f-1042fbc41d62', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 16, 16, 'You didn''t choose me, but I chose you, and appointed you, that you should go and bear fruit, and that your fruit should remain; that whatever you will ask of the Father in my name, he may give it to you.'),
  ('5da2180b-3498-5de3-a437-26c85f4718e6', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 17, 17, '"I command these things to you, that you may love one another.'),
  ('b8fc75cd-7389-5f07-ab03-3a3f62708c73', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 18, 18, 'If the world hates you, you know that it has hated me before it hated you.'),
  ('fedb9d58-63dc-58d8-a96e-398ee10815c5', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 19, 19, 'If you were of the world, the world would love its own. But because you are not of the world, since I chose you out of the world, therefore the world hates you.'),
  ('4dda4efc-7386-5506-aa44-287cc6458426', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 20, 20, 'Remember the word that I said to you: ''A servant is not greater than his lord.'' If they persecuted me, they will also persecute you. If they kept my word, they will keep yours also.'),
  ('c247c4c8-12f7-54c1-a1a4-92e499b0a0a8', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 21, 21, 'But all these things will they do to you for my name''s sake, because they don''t know him who sent me.'),
  ('a3aa796d-ea1c-5c3f-a427-3f7c6b32aaf6', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 22, 22, 'If I had not come and spoken to them, they would not have had sin; but now they have no excuse for their sin.'),
  ('3119ca6c-13d0-5967-a216-f99761cb57dc', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 23, 23, 'He who hates me, hates my Father also.'),
  ('b5bcd88b-8f60-5eb1-a0fd-bb0425540252', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 24, 24, 'If I hadn''t done among them the works which no one else did, they wouldn''t have had sin. But now have they seen and also hated both me and my Father.'),
  ('f545d0ec-8c25-5336-a699-642e15a78674', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 25, 25, 'But this happened so that the word may be fulfilled which was written in their law, ''They hated me without a cause.'''),
  ('28e05a2e-7565-5ac0-a95b-8dc6832fb151', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 26, 26, '"When the Counselor has come, whom I will send to you from the Father, the Spirit of truth, who proceeds from the Father, he will testify about me.'),
  ('ae3c189f-ebe3-56ad-ace6-1b1c173b7246', 'b3df58c8-cb3b-5fc4-a23f-0d51185bd90e', NULL, 27, 27, 'You will also testify, because you have been with me from the beginning.'),
  ('78f049ae-65e7-51d6-afaf-de0e032f5ad7', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 1, 1, '"These things have I spoken to you, so that you wouldn''t be caused to stumble.'),
  ('099327b3-f7cd-53e5-a167-3e2926df16ce', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 2, 2, 'They will put you out of the synagogues. Yes, the time comes that whoever kills you will think that he offers service to God.'),
  ('58b7e662-c092-5d85-a883-7e82454fc5d1', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 3, 3, 'They will do these things because they have not known the Father, nor me.'),
  ('03d40938-5e46-5028-a8b1-135122d87074', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 4, 4, 'But I have told you these things, so that when the time comes, you may remember that I told you about them. I didn''t tell you these things from the beginning, because I was with you.'),
  ('6d7960dc-8a53-5cf2-a9a1-9b52b9189744', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 5, 5, 'But now I am going to him who sent me, and none of you asks me, ''Where are you going?'''),
  ('7627fc40-2853-542e-a31a-d1f0ba7782e6', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 6, 6, 'But because I have told you these things, sorrow has filled your heart.'),
  ('270b7660-ab18-5271-abc4-82a8e4588411', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 7, 7, 'Nevertheless I tell you the truth: It is to your advantage that I go away, for if I don''t go away, the Counselor won''t come to you. But if I go, I will send him to you.'),
  ('ba38d3fe-03f3-5f47-a6b9-a56827985cde', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 8, 8, 'When he has come, he will convict the world about sin, about righteousness, and about judgment;'),
  ('b97b4f45-95f2-5dac-a7ae-ac968caf64f3', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 9, 9, 'about sin, because they don''t believe in me;'),
  ('1557331e-c862-531b-a6bd-643841bdd6d4', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 10, 10, 'about righteousness, because I am going to my Father, and you won''t see me any more;'),
  ('a3e9a3b7-745e-58d6-af5f-53a0da5931f2', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 11, 11, 'about judgment, because the prince of this world has been judged.'),
  ('8900a8d3-cfe9-5162-a6b8-86f9d3ca2642', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 12, 12, '"I have yet many things to tell you, but you can''t bear them now.'),
  ('1808f698-dec2-5590-a214-f5ceeceb705b', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 13, 13, 'However when he, the Spirit of truth, has come, he will guide you into all truth, for he will not speak from himself; but whatever he hears, he will speak. He will declare to you things that are coming.'),
  ('1be87fd1-b37c-5859-a845-54d4990b6abd', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 14, 14, 'He will glorify me, for he will take from what is mine, and will declare it to you.'),
  ('4ba55f6e-e853-5fcb-a944-dfac67240b58', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 15, 15, 'All things whatever the Father has are mine; therefore I said that he takes of mine, and will declare it to you.'),
  ('bd4b3c9e-1e57-5aa5-a732-8195ff88da78', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 16, 16, 'A little while, and you will not see me. Again a little while, and you will see me."'),
  ('89d39572-ce12-535a-ad78-92a79bee958a', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 17, 17, 'Some of his disciples therefore said to one another, "What is this that he says to us, ''A little while, and you won''t see me, and again a little while, and you will see me;'' and, ''Because I go to the Father?''"'),
  ('1e0ed6d4-c301-575d-aab6-ad755308141b', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 18, 18, 'They said therefore, "What is this that he says, ''A little while?'' We don''t know what he is saying."'),
  ('73ba65d9-63a8-59c7-a131-660361c8d30d', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 19, 19, 'Therefore Jesus perceived that they wanted to ask him, and he said to them, "Do you inquire among yourselves concerning this, that I said, ''A little while, and you won''t see me, and again a little while, and you will see me?'''),
  ('686daedf-5719-5112-af2b-a3b7a0b24b4f', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 20, 20, 'Most certainly I tell you, that you will weep and lament, but the world will rejoice. You will be sorrowful, but your sorrow will be turned into joy.'),
  ('32593c72-244a-5e64-ae7a-ae7d4d606d45', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 21, 21, 'A woman, when she gives birth, has sorrow, because her time has come. But when she has delivered the child, she doesn''t remember the anguish any more, for the joy that a human being is born into the world.'),
  ('20888436-4479-59ef-acb6-09955c5e9e82', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 22, 22, 'Therefore you now have sorrow, but I will see you again, and your heart will rejoice, and no one will take your joy away from you.'),
  ('d3d867a6-7104-55c7-a1d0-907a0ba25721', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 23, 23, '"In that day you will ask me no questions. Most certainly I tell you, whatever you may ask of the Father in my name, he will give it to you.'),
  ('4c64dc01-736f-5111-aee5-1014200cc474', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 24, 24, 'Until now, you have asked nothing in my name. Ask, and you will receive, that your joy may be made full.'),
  ('ab2aea1c-47fe-5684-a4d8-f903692347b5', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 25, 25, 'I have spoken these things to you in figures of speech. But the time is coming when I will no more speak to you in figures of speech, but will tell you plainly about the Father.'),
  ('8c487605-f953-5a9f-a3e4-4c29728e5163', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 26, 26, 'In that day you will ask in my name; and I don''t say to you, that I will pray to the Father for you,'),
  ('7b71900c-1928-5570-a33a-8287843eb11b', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 27, 27, 'for the Father himself loves you, because you have loved me, and have believed that I came forth from God.'),
  ('a7f976d4-1895-58c6-a914-e3d17c610b63', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 28, 28, 'I came out from the Father, and have come into the world. Again, I leave the world, and go to the Father."'),
  ('d13098bf-73a3-5df6-a34b-0c0df4023c64', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 29, 29, 'His disciples said to him, "Behold, now you speak plainly, and speak no figures of speech.'),
  ('df47b224-f54c-5306-ac72-c33bc6a574bc', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 30, 30, 'Now we know that you know all things, and don''t need for anyone to question you. By this we believe that you came forth from God."'),
  ('0e4fb243-00f3-53ae-a622-b38af7745863', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 31, 31, 'Jesus answered them, "Do you now believe?'),
  ('f92bfb05-06e9-56c4-a919-a9d9a3db8737', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 32, 32, 'Behold, the time is coming, yes, and has now come, that you will be scattered, everyone to his own place, and you will leave me alone. Yet I am not alone, because the Father is with me.'),
  ('96d69777-8ee2-518e-aa25-af585751791b', 'aa88a017-8a16-5757-a60a-2392d41f24a0', NULL, 33, 33, 'I have told you these things, that in me you may have peace. In the world you have oppression; but cheer up! I have overcome the world."'),
  ('9f6a512f-bf77-56f0-ae96-48c66d9e0199', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 1, 1, 'Jesus said these things, and lifting up his eyes to heaven, he said, "Father, the time has come. Glorify your Son, that your Son may also glorify you;'),
  ('78f2ee86-7afd-5e14-a1e4-76d411ca8414', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 2, 2, 'even as you gave him authority over all flesh, he will give eternal life to all whom you have given him.'),
  ('fa39b52f-5f68-5b7d-a0ad-ea5b59655d0f', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 3, 3, 'This is eternal life, that they should know you, the only true God, and him whom you sent, Jesus Christ.'),
  ('8ad4d663-6177-5860-a50e-8133eb709c3c', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 4, 4, 'I glorified you on the earth. I have accomplished the work which you have given me to do.'),
  ('c5b68606-d59b-5e6e-adc1-33c5d98e9419', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 5, 5, 'Now, Father, glorify me with your own self with the glory which I had with you before the world existed.'),
  ('763d6193-9279-5aaf-a7fe-1737f58ee7fd', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 6, 6, 'I revealed your name to the people whom you have given me out of the world. They were yours, and you have given them to me. They have kept your word.'),
  ('502d7859-ca10-5d5a-a871-66965a07df2b', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 7, 7, 'Now they have known that all things whatever you have given me are from you,'),
  ('c6055091-0051-56e3-ac12-5da7ff4553f6', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 8, 8, 'for the words which you have given me I have given to them, and they received them, and knew for sure that I came forth from you, and they have believed that you sent me.'),
  ('eccfb5ca-fb44-53e9-ad70-83869a8e6abc', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 9, 9, 'I pray for them. I don''t pray for the world, but for those whom you have given me, for they are yours.'),
  ('8fa168a6-1481-51d9-a76f-f24d0437035b', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 10, 10, 'All things that are mine are yours, and yours are mine, and I am glorified in them.'),
  ('08667171-2c9f-501e-a9c3-52306766a072', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 11, 11, 'I am no more in the world, but these are in the world, and I am coming to you. Holy Father, keep them through your name which you have given me, that they may be one, even as we are.'),
  ('0f571e76-64ff-5923-a57f-8244a36aca6c', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 12, 12, 'While I was with them in the world, I kept them in your name. Those whom you have given me I have kept. None of them is lost, except the son of destruction, that the Scripture might be fulfilled.'),
  ('9c454d1f-f748-52f1-a26c-9246e936f60b', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 13, 13, 'But now I come to you, and I say these things in the world, that they may have my joy made full in themselves.'),
  ('530db373-23a7-57d4-a5a7-daa29b4a317a', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 14, 14, 'I have given them your word. The world hated them, because they are not of the world, even as I am not of the world.'),
  ('edc2de65-1428-5165-a665-fc78bf65a91f', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 15, 15, 'I pray not that you would take them from the world, but that you would keep them from the evil one.'),
  ('b0e0b3eb-5d24-524f-ae81-7cfc305779e1', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 16, 16, 'They are not of the world even as I am not of the world.'),
  ('dbbf7c1e-54f0-57d0-a497-9d346eb2aba0', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 17, 17, 'Sanctify them in your truth. Your word is truth.'),
  ('89feae0d-0b14-5c42-aaad-db4be5f0ef08', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 18, 18, 'As you sent me into the world, even so I have sent them into the world.'),
  ('85bdc138-c7e1-5c2f-a1de-2dfdd50c1d86', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 19, 19, 'For their sakes I sanctify myself, that they themselves also may be sanctified in truth.'),
  ('e17d6ad4-969d-5241-a411-21246b3d0c39', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 20, 20, 'Not for these only do I pray, but for those also who believe in me through their word,'),
  ('e275ea2d-7cbe-57e8-aa41-6c9ac34e1f17', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 21, 21, 'that they may all be one; even as you, Father, are in me, and I in you, that they also may be one in us; that the world may believe that you sent me.'),
  ('ee54028d-4f98-5958-a1b3-67d7c329f0f5', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 22, 22, 'The glory which you have given me, I have given to them; that they may be one, even as we are one;'),
  ('75cf8c7a-cba2-5da0-a4ca-60978d495474', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 23, 23, 'I in them, and you in me, that they may be perfected into one; that the world may know that you sent me, and loved them, even as you loved me.'),
  ('018e7a17-e73f-50cb-a1d7-62c058984b95', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 24, 24, 'Father, I desire that they also whom you have given me be with me where I am, that they may see my glory, which you have given me, for you loved me before the foundation of the world.'),
  ('d6ce9286-c67c-522d-ac8b-cc4943ac9b5e', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 25, 25, 'Righteous Father, the world hasn''t known you, but I knew you; and these knew that you sent me.'),
  ('28dbb354-fec6-566a-aac7-ec6d7f75a21c', '4b5f256e-0393-57e8-ade2-72a243846dcb', NULL, 26, 26, 'I made known to them your name, and will make it known; that the love with which you loved me may be in them, and I in them."'),
  ('8992d97e-3b46-5e3b-a528-f939a960bd4b', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 1, 1, 'When Jesus had spoken these words, he went out with his disciples over the brook Kidron, where there was a garden, into which he and his disciples entered.'),
  ('6d03da52-d29c-5242-a02c-451c5db093be', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 2, 2, 'Now Judas, who betrayed him, also knew the place, for Jesus often met there with his disciples.'),
  ('aa319e83-802a-5ca8-a125-79b28e84e0f2', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 3, 3, 'Judas then, having taken a detachment of soldiers and officers from the chief priests and the Pharisees, came there with lanterns, torches, and weapons.'),
  ('849bfc43-8b67-580d-a997-f5af2c7a1430', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 4, 4, 'Jesus therefore, knowing all the things that were happening to him, went forth, and said to them, "Who are you looking for?"'),
  ('4e0c7cb1-3528-5dde-acfa-daa786af4716', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 5, 5, 'They answered him, "Jesus of Nazareth." Jesus said to them, "I am he." Judas also, who betrayed him, was standing with them.'),
  ('87c1f11a-0155-512a-abe1-6ec1523f5842', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 6, 6, 'When therefore he said to them, "I am he," they went backward, and fell to the ground.'),
  ('e5400daa-d65a-515d-a1f8-d4559dccd54f', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 7, 7, 'Again therefore he asked them, "Who are you looking for?" They said, "Jesus of Nazareth."'),
  ('88cca69f-0f49-5d9c-a88e-3d2a291f209d', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 8, 8, 'Jesus answered, "I told you that I am he. If therefore you seek me, let these go their way,"'),
  ('6e36fe03-cc64-51e4-aa2f-a7c903d6471e', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 9, 9, 'that the word might be fulfilled which he spoke, "Of those whom you have given me, I have lost none."'),
  ('320c546e-7ca8-5aae-a91d-cc7811c82d3f', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 10, 10, 'Simon Peter therefore, having a sword, drew it, and struck the high priest''s servant, and cut off his right ear. The servant''s name was Malchus.'),
  ('10cee165-ac69-55ce-a3c4-96279e66b793', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 11, 11, 'Jesus therefore said to Peter, "Put the sword into its sheath. The cup which the Father has given me, shall I not surely drink it?"'),
  ('2382bf45-1764-5212-a0a9-9d3e605fdddb', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 12, 12, 'So the detachment, the commanding officer, and the officers of the Jews, seized Jesus and bound him,'),
  ('db42cbfb-f378-5329-a060-ee7181b0475b', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 13, 13, 'and led him to Annas first, for he was father-in-law to Caiaphas, who was high priest that year.'),
  ('84b12217-e97d-5095-a3c7-78f9b131fad6', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 14, 14, 'Now it was Caiaphas who advised the Jews that it was expedient that one man should perish for the people.'),
  ('f6857159-eae6-59d6-a978-f0b0bf06b0b1', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 15, 15, 'Simon Peter followed Jesus, as did another disciple. Now that disciple was known to the high priest, and entered in with Jesus into the court of the high priest;'),
  ('43a0fb4b-bc49-52c8-af77-d10a79b4635d', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 16, 16, 'but Peter was standing at the door outside. So the other disciple, who was known to the high priest, went out and spoke to her who kept the door, and brought in Peter.'),
  ('3dd8bddf-8602-5c90-adaa-6c7c51b9ff9a', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 17, 17, 'Then the maid who kept the door said to Peter, "Are you also one of this man''s disciples?" He said, "I am not."'),
  ('67e5c79d-3bb5-5170-ae5a-2d16c90e8901', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 18, 18, 'Now the servants and the officers were standing there, having made a fire of coals, for it was cold. They were warming themselves. Peter was with them, standing and warming himself.'),
  ('64480de5-26f9-53d0-ad68-9412c9746b88', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 19, 19, 'The high priest therefore asked Jesus about his disciples, and about his teaching.'),
  ('7d436534-c8b8-5ee0-acca-b485a6b5b476', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 20, 20, 'Jesus answered him, "I spoke openly to the world. I always taught in synagogues, and in the temple, where the Jews always meet. I said nothing in secret.'),
  ('41de95a4-636d-5fd4-a502-6b10056fb2b3', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 21, 21, 'Why do you ask me? Ask those who have heard me what I said to them. Behold, these know the things which I said."'),
  ('0d425912-0784-56f2-ad98-2822e17a4630', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 22, 22, 'When he had said this, one of the officers standing by slapped Jesus with his hand, saying, "Do you answer the high priest like that?"'),
  ('9d38e70d-e1ce-5318-a2ea-4c2f842be8f6', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 23, 23, 'Jesus answered him, "If I have spoken evil, testify of the evil; but if well, why do you beat me?"'),
  ('50be4a35-3559-5ccb-a722-ed136ab714ab', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 24, 24, 'Annas sent him bound to Caiaphas, the high priest.'),
  ('5cc131fd-e414-5540-a9fa-4e5d86a2c102', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 25, 25, 'Now Simon Peter was standing and warming himself. They said therefore to him, "You aren''t also one of his disciples, are you?" He denied it, and said, "I am not."'),
  ('34f2dca6-f520-55cf-a63e-14db863e0181', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 26, 26, 'One of the servants of the high priest, being a relative of him whose ear Peter had cut off, said, "Didn''t I see you in the garden with him?"'),
  ('5fa9cfc5-91a6-5b00-a3ba-a216ee68b8a2', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 27, 27, 'Peter therefore denied it again, and immediately the rooster crowed.'),
  ('8674d1de-a597-54be-a08a-945a8cd2c666', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 28, 28, 'They led Jesus therefore from Caiaphas into the Praetorium. It was early, and they themselves didn''t enter into the Praetorium, that they might not be defiled, but might eat the Passover.'),
  ('0095a30e-06b1-5b28-a5d2-6b8d6ecc015c', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 29, 29, 'Pilate therefore went out to them, and said, "What accusation do you bring against this man?"'),
  ('fff242e5-baa3-5262-a569-aa95fd1684f6', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 30, 30, 'They answered him, "If this man weren''t an evildoer, we wouldn''t have delivered him up to you."'),
  ('404ffc02-2dd3-5bc5-a996-d455a0fc419c', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 31, 31, 'Pilate therefore said to them, "Take him yourselves, and judge him according to your law." Therefore the Jews said to him, "It is not lawful for us to put anyone to death,"'),
  ('b4a30512-d041-5d3a-a1b3-73c5afd17d64', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 32, 32, 'that the word of Jesus might be fulfilled, which he spoke, signifying by what kind of death he should die.'),
  ('d4052b73-6752-5048-a2ff-bc64993d23f5', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 33, 33, 'Pilate therefore entered again into the Praetorium, called Jesus, and said to him, "Are you the King of the Jews?"'),
  ('0f77c1b7-a6c9-5b82-a16e-52fcbb299a22', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 34, 34, 'Jesus answered him, "Do you say this by yourself, or did others tell you about me?"'),
  ('2bcdcca7-a82a-5de1-a5b7-cc03e2dffdc8', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 35, 35, 'Pilate answered, "I''m not a Jew, am I? Your own nation and the chief priests delivered you to me. What have you done?"'),
  ('130f0385-bc89-5e4d-a8e8-d801aa0ed1c7', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 36, 36, 'Jesus answered, "My Kingdom is not of this world. If my Kingdom were of this world, then my servants would fight, that I wouldn''t be delivered to the Jews. But now my Kingdom is not from here."'),
  ('0bc39723-2869-5121-a911-d6a14f59fe88', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 37, 37, 'Pilate therefore said to him, "Are you a king then?" Jesus answered, "You say that I am a king. For this reason I have been born, and for this reason I have come into the world, that I should testify to the truth. Everyone who is of the truth listens to my voice."'),
  ('4ad4c185-05a5-5e7e-ac96-cb86fe000c87', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 38, 38, 'Pilate said to him, "What is truth?" When he had said this, he went out again to the Jews, and said to them, "I find no basis for a charge against him.'),
  ('b093fa7c-02a2-576a-ab76-0aa6e3ba40a7', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 39, 39, 'But you have a custom, that I should release someone to you at the Passover. Therefore do you want me to release to you the King of the Jews?"'),
  ('f54aa7fb-cd49-52d7-a65a-f33d8f72352a', 'a427f382-7b2f-55ff-a3fa-849043b35f7b', NULL, 40, 40, 'Then they all shouted again, saying, "Not this man, but Barabbas!" Now Barabbas was a robber.'),
  ('c2a9f8bf-b915-5c6b-adb3-a126986083ea', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 1, 1, 'So Pilate then took Jesus, and flogged him.'),
  ('271e00ac-d48e-5c70-a47d-8fb4fa186813', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 2, 2, 'The soldiers twisted thorns into a crown, and put it on his head, and dressed him in a purple garment.'),
  ('02b36e46-332b-527f-a69c-977849a71edf', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 3, 3, 'They kept saying, "Hail, King of the Jews!" and they kept slapping him.'),
  ('229f4c10-46b3-58bc-af7a-dd28a4f45c4e', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 4, 4, 'Then Pilate went out again, and said to them, "Behold, I bring him out to you, that you may know that I find no basis for a charge against him."'),
  ('a41a6f62-b32d-50c7-ab36-afbea3098651', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 5, 5, 'Jesus therefore came out, wearing the crown of thorns and the purple garment. Pilate said to them, "Behold, the man!"'),
  ('9c0ebf16-bdc8-5506-a570-dd39f7d0257e', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 6, 6, 'When therefore the chief priests and the officers saw him, they shouted, saying, "Crucify! Crucify!" Pilate said to them, "Take him yourselves, and crucify him, for I find no basis for a charge against him."'),
  ('080be5c8-f8b6-5d9b-a2c5-161b637fbeeb', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 7, 7, 'The Jews answered him, "We have a law, and by our law he ought to die, because he made himself the Son of God."'),
  ('b5fbb87f-5110-5db8-ab41-b25aef6d1ea9', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 8, 8, 'When therefore Pilate heard this saying, he was more afraid.'),
  ('38d82c3e-c597-5c71-ab4a-c1a0b8629230', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 9, 9, 'He entered into the Praetorium again, and said to Jesus, "Where are you from?" But Jesus gave him no answer.'),
  ('ed8700d2-f938-50eb-ad64-ccc35dcd1de5', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 10, 10, 'Pilate therefore said to him, "Aren''t you speaking to me? Don''t you know that I have power to release you, and have power to crucify you?"'),
  ('97a78b91-1d69-5a47-a03a-6fc93dd29340', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 11, 11, 'Jesus answered, "You would have no power at all against me, unless it were given to you from above. Therefore he who delivered me to you has greater sin."'),
  ('7e949caa-5837-5e83-a68f-bdc151adc8d5', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 12, 12, 'At this, Pilate was seeking to release him, but the Jews cried out, saying, "If you release this man, you aren''t Caesar''s friend! Everyone who makes himself a king speaks against Caesar!"'),
  ('5d43cc00-70c6-55a4-afc7-a8da495e6ad0', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 13, 13, 'When Pilate therefore heard these words, he brought Jesus out, and sat down on the judgment seat at a place called "The Pavement," but in Hebrew, "Gabbatha."'),
  ('2ea35c72-6165-5908-abc9-0d7e90699fd0', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 14, 14, 'Now it was the Preparation Day of the Passover, at about the sixth hour. He said to the Jews, "Behold, your King!"'),
  ('d8082d7e-23ff-592a-a475-d48771f6a879', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 15, 15, 'They cried out, "Away with him! Away with him! Crucify him!" Pilate said to them, "Shall I crucify your King?" The chief priests answered, "We have no king but Caesar!"'),
  ('b7f58b12-c4c2-5764-a262-107fe2dab694', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 16, 16, 'So then he delivered him to them to be crucified. So they took Jesus and led him away.'),
  ('bd3bcc7b-ae36-51b7-ad57-334b9a7c6407', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 17, 17, 'He went out, bearing his cross, to the place called "The Place of a Skull," which is called in Hebrew, "Golgotha,"'),
  ('8ed6fd5e-ff96-5379-a65a-74f53f936a32', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 18, 18, 'where they crucified him, and with him two others, on either side one, and Jesus in the middle.'),
  ('5cc37456-5e15-5c3f-a1b8-f685790b21d7', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 19, 19, 'Pilate wrote a title also, and put it on the cross. There was written, "JESUS OF NAZARETH, THE KING OF THE JEWS."'),
  ('cfc8ac35-89b0-5c94-a1b9-65cdb87ad7df', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 20, 20, 'Therefore many of the Jews read this title, for the place where Jesus was crucified was near the city; and it was written in Hebrew, in Latin, and in Greek.'),
  ('12cd116b-2b56-5bc7-aa95-d5e53f57a739', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 21, 21, 'The chief priests of the Jews therefore said to Pilate, "Don''t write, ''The King of the Jews,'' but, ''he said, I am King of the Jews.''"'),
  ('fa98963d-2532-5900-abb4-8a8954b5d848', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 22, 22, 'Pilate answered, "What I have written, I have written."'),
  ('b129b82b-2688-5005-a852-34797394b809', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 23, 23, 'Then the soldiers, when they had crucified Jesus, took his garments and made four parts, to every soldier a part; and also the coat. Now the coat was without seam, woven from the top throughout.'),
  ('08eb87e4-0bb6-5492-ad6c-c49e103ad0f6', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 24, 24, 'Then they said to one another, "Let''s not tear it, but cast lots for it to decide whose it will be," that the Scripture might be fulfilled, which says, "They parted my garments among them. For my cloak they cast lots." Therefore the soldiers did these things.'),
  ('7140f3a4-c713-56d8-ae6e-d4238ae96537', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 25, 25, 'But there were standing by the cross of Jesus his mother, and his mother''s sister, Mary the wife of Clopas, and Mary Magdalene.'),
  ('fd1af6f7-7625-5e31-a02a-1163620c1332', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 26, 26, 'Therefore when Jesus saw his mother, and the disciple whom he loved standing there, he said to his mother, "Woman, behold your son!"'),
  ('0be232b3-2486-597a-a49f-f6b920670221', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 27, 27, 'Then he said to the disciple, "Behold, your mother!" From that hour, the disciple took her to his own home.'),
  ('082c44c8-b5d6-5e6a-ac32-7cd98d4b4a0d', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 28, 28, 'After this, Jesus, seeing that all things were now finished, that the Scripture might be fulfilled, said, "I am thirsty."'),
  ('6eaaeee7-3b64-51dd-a988-c35711f8bc60', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 29, 29, 'Now a vessel full of vinegar was set there; so they put a sponge full of the vinegar on hyssop, and held it at his mouth.'),
  ('88863663-885f-5855-a8cd-a42c45ad9cb7', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 30, 30, 'When Jesus therefore had received the vinegar, he said, "It is finished." He bowed his head, and gave up his spirit.'),
  ('ae26b311-f9bb-54ad-a4ec-0f3ecef6dd3c', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 31, 31, 'Therefore the Jews, because it was the Preparation Day, so that the bodies wouldn''t remain on the cross on the Sabbath (for that Sabbath was a special one), asked of Pilate that their legs might be broken, and that they might be taken away.'),
  ('0099b084-b2b8-588b-ad1f-9592da412bdc', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 32, 32, 'Therefore the soldiers came, and broke the legs of the first, and of the other who was crucified with him;'),
  ('99fac846-19ea-5876-a97d-5103c6225007', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 33, 33, 'but when they came to Jesus, and saw that he was already dead, they didn''t break his legs.'),
  ('c746ba6e-9d0e-5b08-a3a2-1f6dba8b9430', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 34, 34, 'However one of the soldiers pierced his side with a spear, and immediately blood and water came out.'),
  ('0ceccef7-087d-5820-a055-3d0dcfc0826a', 'ab4f850a-1027-56b6-a32d-678f09861448', NULL, 35, 35, 'He who has seen has testified, and his testimony is true. He knows that he tells the truth, that you may believe.')
